/** Advanced React Patterns — modules 6–9: in-depth lessons, lesson quizzes and practice pools. */
export const react2Content: Record<string, TopicContent> = {
  'react-gen-9': {
    summary: 'Hooks must run in the same order on every render, so they are called only at the top level of components or custom hooks.',
    lesson: {
      minutes: 8,
      objectives: [
        'State the two Rules of Hooks and where each one applies',
        'Explain why React needs hooks to run in the same order on every render',
        'Predict what breaks when a hook is called inside a condition, loop or early-return path',
        'Rewrite a component that breaks the rules so that it behaves the same without violating them',
      ],
      simple: 'React remembers your state by counting hooks in the order you call them: first hook, second hook, third hook. If one render skips a hook, the count goes wrong and React hands you the wrong values. So always call hooks at the very top of a component, never inside if-statements or loops.',
      blocks: [
        { type: 'text', title: 'Why hooks have rules at all', body: 'Hooks such as useState, useEffect and useContext let a plain function component remember things between renders. They feel like ordinary function calls, so it is tempting to use them anywhere. But hooks are not ordinary: React needs them to behave predictably, and it enforces that through two short rules. Break them and you get confusing bugs: state that belongs to one field suddenly shows up in another, or React throws the error “Rendered more hooks than during the previous render”. If you read Component Mounting and Understanding useEffect dependencies earlier in this course, you already know that React calls your component function again on every render. The Rules of Hooks are what make that repeated calling safe.' },
        { type: 'analogy', body: 'Think of a row of numbered lockers in a school corridor. Your component is a student who gets locker 1, locker 2 and locker 3 in the order they ask for them. On the next day the student simply walks along the row and opens the same lockers in the same order. If the student skips locker 2 one day, they open locker 3 thinking it is locker 2, and take out someone else’s bag. Hooks work the same way: the order of calls is the address.' },
        { type: 'text', title: 'Rule 1: only call hooks at the top level', body: 'Call hooks at the top level of your function component, before any early return. That means never inside an if-statement, a for-loop, a ternary, a callback such as onClick, or a function defined within the component. React does not store hooks by name. For each component it keeps a list of “hook slots” and, on every render, it hands out slot 1 to your first hook call, slot 2 to the second, and so on. This only works if the same hooks are called in the same order every single time. A condition that is true on one render and false on the next changes the order, and every hook after it reads the wrong slot.' },
        { type: 'code', language: 'tsx', caption: 'The first version calls useState only when loggedIn is true. When loggedIn flips from true to false, React sees one hook fewer and reports an error. In the fixed version both the hook and its call order are constant, and the condition moves into the JSX, where it only decides what to show.', code: 'import { useState } from "react";\n\n// Wrong: the hook is skipped on some renders\nfunction Greeting({ loggedIn }: { loggedIn: boolean }) {\n  if (loggedIn) {\n    const [name, setName] = useState("Asha");\n  }\n  return <p>Hello</p>;\n}\n\n// Right: always call the hook, then use a condition\nfunction GreetingFixed({ loggedIn }: { loggedIn: boolean }) {\n  const [name] = useState("Asha");\n  return <p>{loggedIn ? "Hello, " + name : "Please sign in"}</p>;\n}' },
        { type: 'text', title: 'Rule 2: only call hooks from React functions', body: 'Hooks may be called from exactly two places: the body of a function component, and the body of a custom hook (a function whose name starts with “use”, which you will write in the next topic). They must not be called from ordinary helper functions, event handlers, class components, or code outside React. The “use” prefix is a signal for people and for the linter: when you see a function called useCart, you know it may call hooks and so must itself follow the rules. A helper named getCart gives no such promise. If a helper needs state, rename it to start with “use” and call it only from components or other hooks.' },
        { type: 'example', title: 'Worked example: the early return that shifts the slots', body: 'A learner writes a profile card. If user is null the component returns early, otherwise it declares a useState hook after the check. First render: user is null, the component returns before useState, so React records zero hook slots. Second render: user has loaded, the component now calls useState, so React sees one hook more than before and throws “Rendered more hooks than during the previous render”. The same bug can be quieter. With two hooks, useState(name) and useState(age), skipping the first one on a later render makes the second call receive the first slot, so age would show the name. The fix is always the same: move every hook above the early return, and let the early return only decide what JSX to show.' },
        { type: 'code', language: 'tsx', caption: 'All hooks come first, then the early return. The effect itself can check the condition inside its body, which is allowed because the hook call is still unconditional.', code: 'import { useEffect, useState } from "react";\n\ntype User = { name: string } | null;\n\nfunction ProfileCard({ user }: { user: User }) {\n  const [expanded, setExpanded] = useState(false);\n\n  useEffect(() => {\n    if (user) document.title = user.name;\n  }, [user]);\n\n  if (!user) return <p>Loading…</p>;\n\n  return (\n    <button onClick={() => setExpanded(!expanded)}>\n      {expanded ? user.name + " (details)" : user.name}\n    </button>\n  );\n}' },
        { type: 'steps', title: 'How to repair a component that breaks the rules', steps: [
          'Scroll to the top of the component and list every hook call it makes.',
          'Move each hook above any if, loop, ternary or early return.',
          'Put the condition inside the hook’s body instead, for example inside the effect callback.',
          'If the logic is in a loop, create a child component for each item so each one calls its own hooks.',
          'Turn on eslint-plugin-react-hooks, which reports rule violations as you type.',
        ] },
        { type: 'keyTerms', terms: [
          { term: 'Hook', def: 'A special function, named use…, that lets a function component use React features such as state, effects and context.' },
          { term: 'Top level', def: 'The body of a component or custom hook itself, not nested inside a condition, loop or inner function.' },
          { term: 'Call order', def: 'The sequence in which hooks run during a render; React uses it to match each hook to its stored state.' },
          { term: 'Linter rule', def: 'An automatic check (rules-of-hooks) in the editor that flags hooks called conditionally or in the wrong place.' },
        ] },
        { type: 'callout', tone: 'warning', body: 'The most common slip is an early return placed above a hook, such as “if (!data) return null;” followed by useState. Always declare all hooks first, and return only afterwards.' },
        { type: 'callout', tone: 'tip', body: 'Install eslint-plugin-react-hooks. Its rules-of-hooks check catches conditional hooks instantly, and its exhaustive-deps check warns about missing useEffect dependencies.' },
        { type: 'callout', tone: 'fact', body: 'React 19 added a function called use that can be called inside conditions and loops, an exception to Rule 1. It reads a promise or a context, while useState, useEffect and the classic hooks still follow both rules.' },
        { type: 'summary', points: [
          'Call hooks only at the top level of a component or custom hook, never in conditions, loops, nested functions or after an early return.',
          'Call hooks only from function components and custom hooks, never from plain helper functions or class components.',
          'React matches hooks to stored state by call order, so a skipped hook shifts every later hook onto the wrong slot.',
          'Put the condition inside the hook or in the returned JSX, not around the hook call.',
        ] },
      ],
    },
    quiz: [
      { type: 'mcq', q: 'What happens on the render where show changes from true to false?\n\nfunction Panel({ show }) {\n  if (show) {\n    const [open, setOpen] = useState(false);\n  }\n  return <p>Panel</p>;\n}', options: ['React throws an error about rendering fewer hooks than before', 'It re-renders normally and discards open', 'It keeps open and ignores the condition', 'It re-renders but resets all other state in the app'], answer: 0, why: 'React expects the same number of hooks on every render. When show becomes false the useState call is skipped, so the call order no longer matches the stored hook list and React reports an error.', difficulty: 2 },
      { type: 'mcq', q: 'A component declares useState for name and then useState for age, always in that order. How can React tell which state is which?', options: ['It stores hook values by the order of the calls', 'It reads the variable names from your code', 'It gives each hook a random id on every render', 'It compares the initial values you passed'], answer: 0, why: 'Hooks are not looked up by name. React keeps an ordered list of slots per component and hands them out in call order, which is why the order must never change.', difficulty: 1 },
      { type: 'mcq', q: 'Which version follows the Rules of Hooks?\n\nVersion A: if (!user) return null; const [tab, setTab] = useState(0);\nVersion B: const [tab, setTab] = useState(0); if (!user) return null;', options: ['Version A only', 'Version B only', 'Both versions', 'Neither version'], answer: 1, why: 'In version A the early return can skip useState on some renders. In version B useState always runs first, and only the JSX is conditional.', difficulty: 2 },
      { type: 'multi', q: 'Which of these places may call a hook such as useState?', options: ['The body of a function component', 'The body of a custom hook named useCart', 'An onClick handler defined inside a component', 'The body of a for-loop inside a component', 'A plain helper function named getTotal'], answers: [0, 1], why: 'Hooks belong only at the top level of components and custom hooks. Event handlers, loops and ordinary helper functions break the rules.', difficulty: 2 },
      { type: 'truefalse', q: 'Calling useEffect at the top level but checking an if-condition inside the effect callback is allowed by the Rules of Hooks.', answer: true, why: 'The hook call itself is unconditional, so the order stays the same. The condition only controls what the effect body does.', difficulty: 2 },
      { type: 'fill', q: 'Hooks may only be called at the ____ level of a function component or custom hook, never inside conditions or loops.', answer: 'top', accept: ['top-level', 'top level'], why: 'Top-level calls run in the same order on every render, which is what React relies on to match each hook with its stored state.', difficulty: 1 },
      { type: 'order', q: 'Put these steps in the order React effectively experiences them when a component with two hooks renders for the second time.', items: ['The component function is called again', 'The first hook call is matched to slot 1', 'The second hook call is matched to slot 2', 'The component returns its JSX'], why: 'On every render React runs the function from the top, matching hooks to slots in call order, and only then receives the JSX.', difficulty: 2 },
      { type: 'mcq', q: 'A teammate writes a helper outside any component: function loadCount() { const [n] = useState(0); return n; } and calls it from an onClick handler. What is the best fix?', options: ['Wrap the helper call in useEffect', 'Move the helper call into a for-loop', 'Rename it useCount and call it at the top of a component', 'Rename it loadCountHook and keep calling it in the handler'], answer: 2, why: 'A function that uses hooks must be a custom hook, named with use, and called at the top level of a component or another hook. Calling it from a handler still breaks Rule 1.', difficulty: 3 },
    ],
    practice: [
      { type: 'mcq', q: 'This component crashes with “Rendered more hooks than during the previous render”. What is the cause?\n\nfunction Card({ user }) {\n  if (!user) return <p>Loading</p>;\n  const [open, setOpen] = useState(false);\n  return <button>{String(open)}</button>;\n}', options: ['useState cannot hold a boolean', 'A key prop is missing from the component that renders user', 'useState runs only once user has loaded, after an early return', 'Early returns are only allowed in components that never use state'], answer: 2, why: 'On the first render the early return skips useState, and on the next render it runs, so React sees an extra hook. Move useState above the early return.', difficulty: 2 },
      { type: 'mcq', q: 'A list uses items.map and, inside the callback, each row calls useState to remember whether it is expanded. Which fix keeps the rules?', options: ['Wrap the map call in useMemo', 'Create an Item component that calls useState, and render one per row', 'Call useState once per possible item, using a fixed maximum of ten rows', 'Put an if-statement around the map call so hooks run only when items exist'], answer: 1, why: 'Hooks cannot be called inside a loop or callback. A child component gets its own hook list, so each row can call useState at its own top level.', difficulty: 2 },
      { type: 'mcq', q: 'On render 1 a component calls useState(a) then useState(b). On render 2 a condition skips the first call. What does the remaining useState(b) call receive?', options: ['The stored value b, since React tracks hooks by variable name', 'A fresh initial value for b, because React detects the skipped call', 'undefined', 'The stored value belonging to slot 1, which was a'], answer: 3, why: 'The second render has only one hook call, and it is matched to slot 1. So it receives a’s value, not b’s, which is how state ends up in the wrong variable.', difficulty: 3 },
      { type: 'mcq', q: 'What does the “use” prefix on a custom hook name actually do?', options: ['It makes React run the function only once and cache its result between renders, like useMemo', 'It tells people and the linter the function may call hooks and must follow the rules', 'It is required by React for any function that stores or returns state', 'It makes the function asynchronous'], answer: 1, why: 'The prefix is a convention that the linter relies on. It does not change how JavaScript runs the function.', difficulty: 1 },
      { type: 'mcq', q: 'What is the right way to run an effect only when userId is truthy?', options: ['Put the useEffect call inside if (userId)', 'Call useEffect inside a ternary', 'Skip useEffect and call the code directly during render when userId exists', 'Call useEffect always and put if (userId) inside the callback'], answer: 3, why: 'The hook call must stay unconditional. A check inside the callback gives the same behaviour without changing the hook order.', difficulty: 2 },
      { type: 'mcq', q: 'A class component method calls useState. What happens?', options: ['It works, because class methods are ordinary functions and may call any hook freely', 'It is invalid, because hooks work only in function components and custom hooks', 'It works only inside componentDidMount', 'It works if the method name starts with use'], answer: 1, why: 'Class components have their own state API (this.state). Hooks are not available inside them.', difficulty: 1 },
      { type: 'multi', q: 'Which of these snippets break the Rules of Hooks?', options: ['if (ready) { useEffect(run, []); }', 'const [n, setN] = useState(0); at the top of a component', 'for (const id of ids) { useState(id); }', 'const x = cond ? useContext(A) : useContext(B);', 'useEffect(() => { if (ready) run(); }, [ready]);'], answers: [0, 2, 3], why: 'Calling a hook inside an if, a loop or a ternary changes the call order. A condition placed inside the effect callback is fine.', difficulty: 2 },
      { type: 'multi', q: 'Which of these are real consequences of calling a hook conditionally?', options: ['React may report that it rendered more or fewer hooks than before', 'State values can end up attached to the wrong variable', 'The component stops being a valid JavaScript function', 'The linter plugin reports a rules-of-hooks error'], answers: [0, 1, 3], why: 'A changing call order produces runtime errors or misplaced state, and the linter flags it. The component is still syntactically valid, it simply behaves unpredictably.', difficulty: 3 },
      { type: 'truefalse', q: 'A custom hook named useCart may itself call useState and useEffect, as long as it does so at its own top level.', answer: true, why: 'Custom hooks are composed of other hooks. The rules apply to them exactly as they apply to components.', difficulty: 1 },
      { type: 'truefalse', q: 'Passing an array of dependencies to useEffect lets you call it inside an if-statement safely.', answer: false, why: 'The dependency array controls when the effect runs, not whether the hook is called. Calling it inside an if still changes the hook order.', difficulty: 2 },
      { type: 'fill', q: 'To catch rule violations automatically, add the ESLint plugin called eslint-plugin-react-____ to your project.', answer: 'hooks', accept: ['hook'], why: 'eslint-plugin-react-hooks includes rules-of-hooks and exhaustive-deps, both of which prevent common hook bugs.', difficulty: 1 },
      { type: 'code', q: 'Fix the component so it follows the Rules of Hooks. Keep both the hook and the early return, but make the hook run on every render.', language: 'tsx', starter: 'function Note({ text }: { text?: string }) {\n  if (!text) return <p>No note</p>;\n  const [open, setOpen] = useState(false);\n  return <p onClick={() => setOpen(!open)}>{open ? text : "Show"}</p>;\n}', solution: 'function Note({ text }: { text?: string }) {\n  const [open, setOpen] = useState(false);\n  if (!text) return <p>No note</p>;\n  return <p onClick={() => setOpen(!open)}>{open ? text : "Show"}</p>;\n}', checks: [{ label: 'Still calls useState', pattern: String.raw`useState\s*\(` }, { label: 'useState comes before the early return', pattern: String.raw`useState\s*\([\s\S]*if\s*\(\s*!\s*text\s*\)\s*return` }], why: 'Moving useState above the early return makes the hook run on every render, so the call order never changes.', difficulty: 2 },
    ],
  },
  'react-2': {
    summary: 'A custom hook is a use-named function that bundles stateful logic so many components can share behaviour without sharing markup.',
    lesson: {
      minutes: 8,
      objectives: [
        'Write a custom hook that combines useState and useEffect and returns a useful value',
        'Explain why two components calling the same custom hook get separate state',
        'Choose between returning an array and returning an object from a hook',
        'Spot duplicated component logic that is worth extracting into a hook',
      ],
      simple: 'A custom hook is a function whose name starts with “use” and which calls other hooks inside it. You move repeated logic, such as “track whether the internet is online”, into it once, and then any component can call it. Each component gets its own private copy of the state.',
      blocks: [
        { type: 'text', title: 'Sharing behaviour, not markup', body: 'Imagine three screens in a bus-booking app. Each one needs to know whether the phone is online, so each one writes the same useState and the same useEffect with two event listeners. Copy-pasting works until you find a bug: now you must fix it in three places. A custom hook solves this. It is an ordinary function, named with the prefix “use”, that calls other hooks and returns whatever the components need. The Rules of Hooks you just learned apply inside it, and in return you can call it from any component. A custom hook shares logic only; each component still decides what to draw.' },
        { type: 'analogy', body: 'A custom hook is like a recipe card for making masala chai. The card does not contain any actual tea. Every household that follows it brews its own pot with its own cups. Two components that call the same hook follow the same recipe, but each gets its own private pot of state, so one component’s changes never leak into the other.' },
        { type: 'text', title: 'Building one step by step', body: 'Start from a component that already works, such as one that tracks online status. Cut the useState and useEffect lines out of it, paste them into a new function called useOnline, and return the value the component needs. In the component, replace the removed lines with one call: const online = useOnline(). Behaviour is unchanged, but the component now reads like a sentence. Notice that the cleanup function, which removes the event listeners, travels with the effect. That is a big win: anyone who calls useOnline gets correct cleanup for free, exactly as you learned in Cleanup Functions in useEffect.' },
        { type: 'code', language: 'tsx', caption: 'useOnline owns a boolean state and subscribes to the browser’s online and offline events. The effect returns a cleanup that removes both listeners when the component unmounts. StatusBadge now contains no effect code at all, only a call to the hook.', code: 'import { useEffect, useState } from "react";\n\nfunction useOnline(): boolean {\n  const [online, setOnline] = useState(navigator.onLine);\n  useEffect(() => {\n    const on = () => setOnline(true);\n    const off = () => setOnline(false);\n    window.addEventListener("online", on);\n    window.addEventListener("offline", off);\n    return () => {\n      window.removeEventListener("online", on);\n      window.removeEventListener("offline", off);\n    };\n  }, []);\n  return online;\n}\n\nfunction StatusBadge() {\n  const online = useOnline();\n  return <span>{online ? "Online" : "Offline"}</span>;\n}' },
        { type: 'text', title: 'Each call gets its own state', body: 'A very common misunderstanding is that custom hooks share state, like a global variable. They do not. Every time a component calls useOnline, the useState inside it creates a brand-new slot belonging to that component instance. If StatusBadge appears twice on a page, there are two separate states. They happen to show the same value here only because both listen to the same browser event. If you want components to share one actual state value, you lift the state up to a parent or use Context, which comes in the next module.' },
        { type: 'text', title: 'Arguments, return values and design', body: 'A hook can take arguments, for example useLocalStorage(key, initial), and may return anything: a value, a tuple or an object. Return an array when callers will usually rename the values, as useState does, because array destructuring lets each caller pick its own names: const [open, toggleOpen] = useToggle(). Return an object when there are many values or when their order would be easy to confuse. In TypeScript, a tuple return needs “as const” or an explicit return type, otherwise the array is inferred as a union of its element types and destructuring becomes awkward.' },
        { type: 'code', language: 'tsx', caption: 'useToggle takes an initial value and returns a pair: the current boolean and a function that flips it. Using setValue with an updater function (v) => !v makes the flip correct even when called several times quickly. “as const” keeps the pair as a tuple.', code: 'import { useState } from "react";\n\nfunction useToggle(initial = false) {\n  const [value, setValue] = useState(initial);\n  const toggle = () => setValue((v) => !v);\n  return [value, toggle] as const;\n}\n\nfunction Accordion() {\n  const [open, toggleOpen] = useToggle();\n  return (\n    <section>\n      <button onClick={toggleOpen}>Details</button>\n      {open && <p>Platform 4, 06:15 express</p>}\n    </section>\n  );\n}' },
        { type: 'example', title: 'Worked example: extracting useLocalStorage', body: 'A settings page keeps a theme in state and also saves it with localStorage. The component has useState(() => localStorage.getItem("theme") ?? "light") and a useEffect that calls localStorage.setItem("theme", theme) whenever theme changes. Another page needs the same for the font size. Step 1: copy the two hooks into a function useLocalStorage(key, initial). Step 2: replace the hard-coded "theme" with key and "light" with initial. Step 3: return [value, setValue]. Now the settings page says const [theme, setTheme] = useLocalStorage("theme", "light"), and the other page says const [size, setSize] = useLocalStorage("fontSize", "16"). Two lines replace about ten, and the saving logic lives in one place. The same trick works for useWindowWidth, useDebounce, or any logic that mixes state with effects.' },
        { type: 'keyTerms', terms: [
          { term: 'Custom hook', def: 'A function named use… that calls other hooks and lets components reuse stateful logic.' },
          { term: 'Extraction', def: 'Moving repeated state and effect code out of a component into a separate function.' },
          { term: 'Tuple return', def: 'Returning a fixed-length array, such as [value, toggle], so callers can name the parts themselves.' },
          { term: 'Instance state', def: 'State owned by one component instance; each call to a custom hook creates its own copy.' },
        ] },
        { type: 'callout', tone: 'warning', body: 'Custom hooks do not make state global. If two components must stay in sync, the state has to live in a common parent or in Context, not merely in a shared hook.' },
        { type: 'callout', tone: 'tip', body: 'Extract a hook when you see the same state plus effect combination for the second or third time, or when a component’s effects obscure what it renders. Don’t extract a hook that wraps just one useState and nothing else.' },
        { type: 'summary', points: [
          'A custom hook is a function whose name starts with use and which calls other hooks; it shares logic, not markup.',
          'Every call to a custom hook creates separate state for that component, so two components using useOnline do not share one value.',
          'Effect cleanup placed inside the hook protects every component that uses it.',
          'Return a tuple when callers will rename values, and an object when there are many values; add as const in TypeScript for tuples.',
        ] },
      ],
    },
    quiz: [
      { type: 'mcq', q: 'Two components both call useToggle(). One calls toggle(). What happens to the other component’s value?', options: ['It stays as it was', 'It flips as well', 'It resets to the initial value', 'It throws an error'], answer: 0, why: 'Each call to a custom hook creates its own state slot inside the calling component, so state is not shared between components.', difficulty: 2 },
      { type: 'mcq', q: 'Which of these is a valid custom hook?', options: ['function getWidth() { const [w] = useState(0); return w; }', 'function useWidth() { const [w] = useState(0); return w; }', 'function useWidth() { return window.innerWidth; }', 'const width = useState(0);'], answer: 1, why: 'A custom hook is named with the use prefix and calls other hooks. getWidth has the wrong name, a useWidth that only returns window.innerWidth calls no hooks, and const width = useState(0) is a value, not a function.', difficulty: 2 },
      { type: 'mcq', q: 'A component contains this effect, and three other components copy it:\n\nuseEffect(() => {\n  const id = setInterval(tick, 1000);\n  return () => clearInterval(id);\n}, []);\n\nWhat is the best refactor?', options: ['Move the effect to a global variable that every component can import and run', 'Use a different dependency array in each copy so every interval is unique', 'Move it into a function called useTicker and call that in each component', 'Convert each component into a class'], answer: 2, why: 'Repeated state or effect logic belongs in a custom hook. The cleanup also moves with the effect, so every caller is protected.', difficulty: 2 },
      { type: 'multi', q: 'Which of these are true about a custom hook such as useOnline?', options: ['It may call useState and useEffect', 'It must be called at the top level of a component or another hook', 'It lets two components share the same state value automatically', 'Its name should start with use'], answers: [0, 1, 3], why: 'Custom hooks are built from other hooks and follow the same rules. They share logic, but each caller still gets separate state.', difficulty: 2 },
      { type: 'truefalse', q: 'A custom hook can return an object or a tuple, and whichever shape you pick, callers receive the values without any extra React feature.', answer: true, why: 'A hook is a plain function, so it can return anything. Tuples suit renamable pairs like [value, setValue]; objects suit larger APIs.', difficulty: 1 },
      { type: 'fill', q: 'In TypeScript, add “as ____” after [value, toggle] in a hook’s return statement so the result is typed as a fixed tuple.', answer: 'const', accept: ['const;'], why: '“as const” stops TypeScript from widening the array to a union type array, so destructuring gives each element its own type.', difficulty: 2 },
      { type: 'code', q: 'Write a custom hook useToggle(initial) that returns [value, toggle], where toggle flips the value.', language: 'tsx', starter: 'function useToggle(initial = false) {\n  \n}', solution: 'function useToggle(initial = false) {\n  const [value, setValue] = useState(initial);\n  const toggle = () => setValue((v) => !v);\n  return [value, toggle];\n}', checks: [{ label: 'Named useToggle', pattern: String.raw`(function|const)\s+useToggle\b` }, { label: 'Keeps state with useState', pattern: String.raw`useState\s*\(` }, { label: 'Flips the value', pattern: String.raw`!\s*\w+` }, { label: 'Returns [value, toggle]', pattern: String.raw`return\s*\[` }], why: 'A custom hook is a function starting with use that calls other hooks and returns what callers need.', difficulty: 3 },
      { type: 'mcq', q: 'A component calls const [size, setSize] = useLocalStorage("fontSize", "16"). Which hook signature fits this call?', options: ['useLocalStorage(initial, key)', 'useLocalStorage(key, initial)', 'useLocalStorage(setSize)', 'useLocalStorage()'], answer: 1, why: 'The call passes the storage key first and the initial value second, and the hook returns a [value, setter] pair like useState.', difficulty: 1 },
    ],
    practice: [
      { type: 'mcq', q: 'A page shows <StatusBadge /> twice, and StatusBadge uses useOnline(). How many separate online states exist?', options: ['One, shared by both', 'Two, one per component instance', 'Zero, because hooks do not hold state', 'One for each event listener'], answer: 1, why: 'The useState inside a custom hook belongs to each calling component instance, so two badges mean two states.', difficulty: 2 },
      { type: 'mcq', q: 'Which hook design is best for a function that returns a loading flag, data, an error and a refetch function?', options: ['A tuple of four items without names', 'Four separate hooks that each repeat the same fetch call', 'An object such as { data, loading, error, refetch }', 'A global variable'], answer: 2, why: 'With four values, an object makes the call site readable and avoids mixing up positions in a destructured array.', difficulty: 2 },
      { type: 'mcq', q: 'Here is a hook:\n\nfunction useCounter() {\n  const [n, setN] = useState(0);\n  return [n, () => setN(n + 1)];\n}\n\nA parent renders two <Counter /> components that each call useCounter, and the user clicks the first one three times. What does the second one display?', options: ['3', '0', '6', '1'], answer: 1, why: 'Each Counter has its own state slot from its own useCounter call, so the second counter is unaffected and still shows 0.', difficulty: 2 },
      { type: 'mcq', q: 'A component has an effect that adds a window resize listener and removes it in cleanup, and four more components need the same. What do you gain by extracting a useWindowWidth hook?', options: ['The listener is attached only once for the whole app', 'Duplicate code disappears and the cleanup is written once', 'The components no longer re-render on resize', 'React skips the Rules of Hooks inside it'], answer: 1, why: 'Extraction centralises the logic and cleanup. Each component still attaches its own listener and still re-renders when the width changes.', difficulty: 3 },
      { type: 'mcq', q: 'Which situation is the weakest reason to create a custom hook?', options: ['A component wraps one useState with no other logic and is used once', 'The same fetch, state and cleanup code is pasted in five components', 'A long effect hides what the component renders', 'A timer logic needs the same cleanup in several places'], answer: 0, why: 'A hook that only forwards a single useState adds a name but no reuse or clarity. Extract when logic repeats or obscures the component.', difficulty: 2 },
      { type: 'mcq', q: 'What is wrong with this hook?\n\nfunction useSearch(term) {\n  if (!term) return [];\n  const [results, setResults] = useState([]);\n  return results;\n}', options: ['The name is wrong', 'It returns an array instead of an object', 'It has an early return above a hook call', 'It takes a parameter that changes between renders'], answer: 2, why: 'Custom hooks follow the Rules of Hooks, so the early return can skip useState and change the hook order between renders.', difficulty: 2 },
      { type: 'multi', q: 'Which of these are good candidates for a custom hook?', options: ['Tracking the browser width with state and a resize listener', 'A one-off piece of JSX for a footer', 'Syncing a value to localStorage with state and an effect', 'A debounce delay that uses state and a timer effect', 'A constant such as const TAX = 0.18'], answers: [0, 2, 3], why: 'Hooks are for reusable logic that uses state or effects. Static markup and constants have no stateful logic to share.', difficulty: 2 },
      { type: 'multi', q: 'In a hook that returns [value, setValue], which statements are correct?', options: ['Callers can choose their own names for the two items', 'In TypeScript, as const keeps the result a tuple', 'Both items must have the same type', 'The order of items matters to every caller'], answers: [0, 1, 3], why: 'Array destructuring lets callers rename the parts, as const keeps tuple types, and position defines meaning. The two items may have different types.', difficulty: 2 },
      { type: 'truefalse', q: 'If two components call the same custom hook, they automatically stay in sync with each other.', answer: false, why: 'Each call creates separate state. Components stay in sync only when they read the same lifted state or Context value.', difficulty: 2 },
      { type: 'truefalse', q: 'A custom hook can include an effect with cleanup, and every component that uses the hook benefits from that cleanup.', answer: true, why: 'The effect and its cleanup belong to the component that called the hook, so cleanup runs on unmount for each caller.', difficulty: 1 },
      { type: 'fill', q: 'A function that calls useState and useEffect and is shared between components must have a name that begins with ____.', answer: 'use', accept: ['use…', '"use"'], why: 'The use prefix signals the function is a hook, and it lets the linter enforce the Rules of Hooks inside it.', difficulty: 1 },
      { type: 'code', q: 'Write a custom hook useCounter(start) that keeps a number in state and returns an object { count, increment } where increment adds 1.', language: 'tsx', starter: 'function useCounter(start = 0) {\n  \n}', solution: 'function useCounter(start = 0) {\n  const [count, setCount] = useState(start);\n  const increment = () => setCount((c) => c + 1);\n  return { count, increment };\n}', checks: [{ label: 'Named useCounter', pattern: String.raw`(function|const)\s+useCounter\b` }, { label: 'Uses useState', pattern: String.raw`useState\s*\(` }, { label: 'Adds 1', pattern: String.raw`\+\s*1|\+\+` }, { label: 'Returns count and increment', pattern: String.raw`return\s*\{[^}]*count[^}]*increment|return\s*\{[^}]*increment[^}]*count` }], why: 'The hook owns the state, exposes a way to change it, and returns both in an object that callers can destructure.', difficulty: 2 },
    ],
  },
  'react-gen-10': {
    summary: 'Well-designed custom hooks compose other hooks, take arguments, handle async work and cleanup safely, and expose a small, clear API.',
    lesson: {
      minutes: 8,
      objectives: [
        'Compose a larger custom hook from smaller hooks such as useState, useEffect and a debounce hook',
        'Write a data-fetching hook that ignores stale responses using a cleanup flag',
        'Diagnose bugs caused by missing or unstable arguments in a hook’s dependency array',
        'Design a hook’s return value so that callers get a small, clear API',
      ],
      simple: 'Once you know how to write a custom hook, the next skill is writing good ones. Good hooks are small, can be built from other hooks, clean up after themselves and react correctly when their inputs change. A fetching hook, for example, must ignore an old answer that arrives late.',
      blocks: [
        { type: 'text', title: 'From first hook to well-designed hook', body: 'In Custom hooks you extracted useOnline and useToggle. Real apps ask for more: fetching data, delaying a search until the user stops typing, reading from storage. These hooks take inputs that change over time, run asynchronous work, and need to behave correctly when the component unmounts. That is where careless hooks cause bugs: flickering results, warnings about updating unmounted components, or effects that run on every render. This lesson is about the design habits that prevent them. The good news is that nothing new is required from React; you combine useState, useEffect and the Rules of Hooks you already know.' },
        { type: 'analogy', body: 'A well-made custom hook is like a good electrical plug-and-socket: simple on the outside, with a standard shape, and the wiring is hidden inside. A caller only needs to know what to plug in (arguments) and what comes out (return value). If the plug has a loose wire, such as a missing cleanup, every appliance connected to it is at risk.' },
        { type: 'text', title: 'Hooks can call hooks', body: 'Because a custom hook is just a function that follows the Rules of Hooks, it can call other custom hooks. This is composition: build small hooks, then combine them. For example, useDebounce(value, delay) returns a copy of value that only changes after the user has stopped changing it for delay milliseconds. A useSearch(query) hook can call useDebounce first, then fetch with the debounced value. Each piece is simple, testable in isolation and reusable elsewhere. Remember that the Rules of Hooks apply at every level: inner hooks must also be called unconditionally, in the same order, at the top of the outer hook.' },
        { type: 'text', title: 'Async work, cleanup and stale responses', body: 'Suppose useFetch(url) starts a request inside useEffect. The user quickly moves from product 1 to product 2. Two requests are now in flight, and if the slower request for product 1 arrives last it would overwrite the correct data. The standard fix uses the cleanup function from Cleanup Functions in useEffect. Create a flag, ignore = false, inside the effect. When the effect re-runs or the component unmounts, React calls the cleanup, which sets ignore = true. When a response arrives, only call setData if ignore is still false. An AbortController achieves a similar result by cancelling the request itself.' },
        { type: 'code', language: 'tsx', caption: 'useFetch keeps data, loading and error in state. The effect depends on url, so it re-runs when the url changes. The cleanup sets ignore to true, so a response from the previous url is discarded. The hook returns an object because there are three values.', code: 'import { useEffect, useState } from "react";\n\nfunction useFetch<T>(url: string) {\n  const [data, setData] = useState<T | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n\n  useEffect(() => {\n    let ignore = false;\n    setLoading(true);\n    fetch(url)\n      .then((r) => r.json())\n      .then((json) => { if (!ignore) setData(json); })\n      .catch((e) => { if (!ignore) setError(String(e)); })\n      .finally(() => { if (!ignore) setLoading(false); });\n    return () => { ignore = true; };\n  }, [url]);\n\n  return { data, loading, error };\n}' },
        { type: 'text', title: 'Inputs, dependencies and a small API', body: 'Everything a hook reads from its arguments and uses inside an effect must appear in the dependency array, exactly as in Understanding useEffect dependencies. Primitive arguments such as strings and numbers are safe. Objects, arrays and functions are created fresh on every render, so if a caller passes { page: 2 } inline and you list it as a dependency, the effect runs on every render. Either depend on the primitive fields you use, or document that callers must memoise the value. Finally, keep the returned API small and stable: return only what callers need, name things clearly, and avoid returning internal setters that let callers break your invariants.' },
        { type: 'example', title: 'Worked example: a debounced search', body: 'A search box types “r”, “re”, “rea”, “reac”, “react” within one second. Without debouncing, five requests fire. Build useDebounce: const [debounced, setDebounced] = useState(value); then useEffect(() => { const id = setTimeout(() => setDebounced(value), delay); return () => clearTimeout(id); }, [value, delay]); return debounced. Every keystroke changes value, which runs the cleanup of the previous effect (cancelling its timer) and starts a new timer. Only after 300 ms of silence does the timer fire, so debounced becomes “react”. Then in useSearch: const q = useDebounce(query, 300); const { data } = useFetch(q ? "/api/search?q=" + q : "/api/empty"). Result: a single request for “react”, and each hook remains small enough to understand at a glance.' },
        { type: 'compare', title: 'Careless hook versus well-designed hook', columns: ['Careless hook', 'Well-designed hook'], rows: [
          ['Cleanup', 'None; stale responses overwrite new data', 'Ignore flag or abort in the cleanup function'],
          ['Dependencies', 'Empty array even though url is used', 'Lists every value the effect reads'],
          ['Return value', 'Exposes every internal setter', 'Returns only what callers need'],
          ['Structure', 'One large hook doing everything', 'Small hooks composed together'],
        ] },
        { type: 'keyTerms', terms: [
          { term: 'Composition', def: 'Building a larger hook by calling smaller hooks inside it.' },
          { term: 'Debounce', def: 'Waiting until a value has stopped changing for a set time before acting on it.' },
          { term: 'Stale response', def: 'An old network reply that arrives after a newer request and could overwrite correct data.' },
          { term: 'AbortController', def: 'A browser tool for cancelling an in-flight fetch request.' },
        ] },
        { type: 'callout', tone: 'warning', body: 'Leaving a url or id out of the dependency array, “to stop it running too often”, makes the hook show stale data. Fix the cause of the extra runs instead, for example an object created on every render.' },
        { type: 'callout', tone: 'tip', body: 'In real projects, reach for a tested data-fetching library such as TanStack Query for caching and retries. Writing useFetch yourself is still the best way to understand what those libraries do.' },
        { type: 'summary', points: [
          'Custom hooks can call other custom hooks, which lets you build complex behaviour from small, testable pieces.',
          'Async hooks should return a cleanup that ignores or aborts outdated requests, so a slow old response never overwrites newer data.',
          'List every argument the effect uses in its dependency array, and beware inline objects or functions that change on every render.',
          'Return a small, clear API, using an object when there are several values.',
        ] },
      ],
    },
    quiz: [
      { type: 'mcq', q: 'In this hook, a user changes id from 1 to 2 quickly and the response for id 1 arrives last. What stops it from overwriting the data?\n\nuseEffect(() => {\n  let ignore = false;\n  fetch("/api/item/" + id).then(r => r.json()).then(d => { if (!ignore) setItem(d); });\n  return () => { ignore = true; };\n}, [id]);', options: ['The cleanup sets ignore to true before the next effect runs', 'React cancels old fetch calls itself', 'The dependency array blocks stale values', 'setItem ignores values from earlier renders'], answer: 0, why: 'When id changes, React runs the previous effect’s cleanup, which flips its own ignore flag. The late response then skips setItem.', difficulty: 2 },
      { type: 'mcq', q: 'A hook is written as useEffect(() => { fetch("/api/user/" + userId).then(save); }, []) . The component receives a new userId. What happens?', options: ['The fetch runs again for the new userId because props changed', 'The fetch keeps using the old userId and shows stale data', 'React throws an error immediately', 'The component unmounts'], answer: 1, why: 'An empty dependency array means the effect runs only after the first render. The new userId is never fetched, which is why every value the effect reads must be listed.', difficulty: 2 },
      { type: 'mcq', q: 'useDebounce(value, 300) is used in a search box. A user types five letters within one second and then stops. How many times does the debounced value change?', options: ['Five times, once for each letter typed', 'Three times, once per second of typing', 'Never', 'Once, after the typing stops'], answer: 3, why: 'Each keystroke cancels the previous timer through the effect’s cleanup. Only the last timer survives for 300 ms and updates the value once.', difficulty: 2 },
      { type: 'multi', q: 'Which of these practices make a data-fetching custom hook more reliable?', options: ['Returning a cleanup that ignores outdated responses', 'Listing the url in the effect’s dependency array', 'Using an empty dependency array even when the url changes', 'Handling the error case and returning it', 'Calling the fetch directly in the render body'], answers: [0, 1, 3], why: 'Cleanup, correct dependencies and error handling prevent stale or missing data. Fetching in the render body would trigger a request on every render.', difficulty: 2 },
      { type: 'truefalse', q: 'A custom hook may call another custom hook, as long as it does so at its top level.', answer: true, why: 'Hooks compose. For example useSearch can call useDebounce and useFetch, following the same Rules of Hooks as a component.', difficulty: 1 },
      { type: 'fill', q: 'A flag set to true in an effect’s ____ function lets a fetching hook ignore a response that arrives after the component has changed or unmounted.', answer: 'cleanup', accept: ['clean-up', 'clean up', 'return'], why: 'React runs the cleanup returned by an effect before re-running it and on unmount, which is the right moment to mark older requests as outdated.', difficulty: 1 },
      { type: 'mcq', q: 'A hook receives options and lists it in useEffect dependencies. A caller writes useThing({ page: 2 }) inline. What is the likely symptom?', options: ['The effect never runs', 'The effect runs on every render', 'TypeScript rejects the call', 'The effect runs once only'], answer: 1, why: 'An object literal is a new object on each render, so React sees a changed dependency each time. Depend on options.page, or have callers memoise the object.', difficulty: 3 },
      { type: 'match', q: 'Match each hook design problem to its fix.', pairs: [['Stale response overwrites newer data', 'Ignore flag set in cleanup'], ['Effect re-runs on every render', 'Depend on primitives, not inline objects'], ['Too many requests per keystroke', 'Debounce the input value'], ['Hook does many unrelated things', 'Split into smaller composed hooks']], why: 'Each symptom has a standard remedy: cleanup for stale data, stable dependencies for extra runs, debouncing for request storms, and composition for large hooks.', difficulty: 2 },
    ],
    practice: [
      { type: 'mcq', q: 'useSearch(query) first calls useDebounce(query, 300) and then useFetch with the result. Which statement about this is correct?', options: ['A hook calling two other hooks is composition and follows the normal rules', 'Hooks cannot call other custom hooks, only React built-ins such as useState', 'It breaks the Rules of Hooks because the call chain is two levels deep', 'Only components can call useFetch'], answer: 0, why: 'Custom hooks are allowed to call other hooks at their top level, so composing small hooks is a normal and encouraged design.', difficulty: 1 },
      { type: 'mcq', q: 'Here is a hook:\n\nfunction useTitle(text) {\n  useEffect(() => { document.title = text; }, []);\n}\n\nThe component passes a new text after a button click, but the browser tab title does not change. Why?', options: ['document.title is read-only', 'text is missing from the dependency array', 'useEffect cannot touch the document', 'The hook should be named useTitleHook'], answer: 1, why: 'With an empty array the effect runs only once, using the first text. Adding text to the dependencies makes it run whenever text changes.', difficulty: 2 },
      { type: 'mcq', q: 'A fetching hook shows “Cannot update state on an unmounted component” style bugs when a user leaves the page quickly. Which change addresses the cause?', options: ['Check an ignore flag set in the effect’s cleanup before calling setState', 'Add more useState calls', 'Move the fetch into the render body so it runs before any cleanup can fire', 'Remove the dependency array so the effect stops reacting to changes'], answer: 0, why: 'The response can arrive after unmount. A cleanup-controlled flag, or an AbortController, stops it from touching state afterwards.', difficulty: 2 },
      { type: 'mcq', q: 'What is the main benefit of returning { data, loading, error } instead of [data, loading, error] from useFetch?', options: ['Objects are faster than arrays because they skip allocation', 'Callers read values by name, so the order cannot be mixed up', 'React requires hooks to return objects so state updates can be tracked', 'Arrays cannot hold null'], answer: 1, why: 'With three similar values, names communicate meaning better than positions. React does not care which shape you return.', difficulty: 1 },
      { type: 'code', q: 'Write a hook useDebounce(value, delay) that returns the value only after it has stayed unchanged for delay milliseconds. Use useState, and useEffect with setTimeout and a cleanup that clears the timer.', language: 'tsx', starter: 'function useDebounce<T>(value: T, delay: number) {\n  \n}', solution: 'function useDebounce<T>(value: T, delay: number) {\n  const [debounced, setDebounced] = useState(value);\n  useEffect(() => {\n    const id = setTimeout(() => setDebounced(value), delay);\n    return () => clearTimeout(id);\n  }, [value, delay]);\n  return debounced;\n}', checks: [{ label: 'Keeps the delayed value in state', pattern: String.raw`useState\s*[<(]` }, { label: 'Starts a timer with setTimeout', pattern: String.raw`setTimeout\s*\(` }, { label: 'Clears the timer in cleanup', pattern: String.raw`clearTimeout\s*\(` }, { label: 'Depends on value', pattern: String.raw`\[\s*value\b` }], why: 'Clearing the previous timer in the cleanup cancels pending updates, so only the last change after a quiet period is applied.', difficulty: 3 },
      { type: 'mcq', q: 'A caller writes useFetch(url, { headers: { Accept: "json" } }) and the hook lists the headers object in its dependencies. The request is sent on every render. What is a sound fix inside the hook?', options: ['Remove the dependency array', 'Depend on the primitive values it needs, such as headers.Accept', 'Call the hook in a loop', 'Wrap the hook call in an if-statement so it only runs on the first render'], answer: 1, why: 'The inline object is a new reference each render. Depending on primitive fields, or asking callers to memoise the options, keeps the dependency stable.', difficulty: 3 },
      { type: 'multi', q: 'Which statements about a well-designed custom hook are correct?', options: ['It should return only what callers need', 'It should be broken into smaller hooks if it grows to do unrelated things', 'It may expose every internal setter to be flexible', 'It should list every value used in its effects as a dependency'], answers: [0, 1, 3], why: 'Small clear APIs, composition and complete dependencies keep hooks safe. Exposing all setters lets callers break the hook’s invariants.', difficulty: 2 },
      { type: 'multi', q: 'Which of these will cause useEffect(() => { load(filters); }, [filters]) to run on every render when filters is received as a prop?', options: ['The parent writes an object literal such as { type: "bus" } directly in the filters prop', 'The parent passes a string variable', 'The parent builds a new array with .filter() during each render and passes it', 'The parent passes a value held in useMemo'], answers: [0, 2], why: 'Inline objects and freshly built arrays have new identity each render. A string or a memoised value keeps the same identity between renders.', difficulty: 3 },
      { type: 'truefalse', q: 'An AbortController can be used inside an effect’s cleanup to cancel an in-flight fetch request.', answer: true, why: 'Calling controller.abort() in cleanup cancels the request, and the fetch promise rejects with an AbortError that you can ignore.', difficulty: 2 },
      { type: 'truefalse', q: 'Setting an empty dependency array is a good way to stop a hook’s effect running too often when its inputs change.', answer: false, why: 'It stops the effect from re-running when inputs change, so the hook uses stale values. The real fix is stabilising the inputs.', difficulty: 2 },
      { type: 'fill', q: 'A hook that returns a copy of a value which only changes after the user stops changing it for a set number of milliseconds is called useDe____.', answer: 'bounce', accept: ['useDebounce', 'debounce'], why: 'Debouncing waits for a quiet period before updating, which avoids sending one request per keystroke.', difficulty: 2 },
      { type: 'order', q: 'Order what happens when the url passed to useFetch changes from "/a" to "/b".', items: ['The component re-renders with the new url', 'The cleanup of the effect for "/a" runs and sets ignore to true', 'The effect runs again and starts a request for "/b"', 'A late response for "/a" arrives and is ignored'], why: 'React runs the previous effect’s cleanup before the next effect, so the old request’s response is marked ignorable by the time it arrives.', difficulty: 3 },
    ],
  },
  'react-gen-11': {
    summary: 'Prop drilling is passing data through intermediate components that do not use it; it can be reduced with composition before reaching for Context.',
    lesson: {
      minutes: 7,
      objectives: [
        'Identify prop drilling in a component tree and name the components that only pass data along',
        'Explain why long chains of props make code harder to change',
        'Refactor a drilled prop using composition with children or an element prop',
        'Decide when drilling a prop two levels is acceptable and when another approach is better',
      ],
      simple: 'Prop drilling means passing a value down through several components, even though only the last one needs it. The middle components just act as postmen. It is fine for a level or two, but in a deep tree it becomes tiring and fragile, so we look for better ways to deliver the data.',
      blocks: [
        { type: 'text', title: 'Passing data down the tree', body: 'In React, data flows one way: from parent to child, through props. This is simple and predictable, and it is the reason React apps are easy to reason about. But there is a catch. Suppose the App component knows the signed-in user’s name, and a small UserMenu button, buried four levels down, needs to display it. The only built-in way to get the name there is to hand it to each component in between: App passes it to Layout, Layout to Sidebar, Sidebar to UserMenu. Layout and Sidebar never use the name. They are only carrying it. This is called prop drilling, like a drill boring through every layer to reach what lies underneath.' },
        { type: 'analogy', body: 'Imagine a letter that must reach a classroom on the fourth floor of a school. There is no lift, so the letter is handed from the gate guard to the office clerk, then to a peon on the stairs, then to the class monitor. Every person in the chain must be told about the letter, even though none of them need to read it. If the letter changes, or a new floor is added to the building, every person in the chain is affected.' },
        { type: 'code', language: 'tsx', caption: 'user is declared once in App, but Layout and Sidebar receive it and forward it unchanged. Only UserMenu reads user.name. If UserMenu later needs user.avatar, you must edit all four components, including their type definitions.', code: 'type User = { name: string };\n\nfunction App() {\n  const user: User = { name: "Meera" };\n  return <Layout user={user} />;\n}\n\nfunction Layout({ user }: { user: User }) {\n  return <Sidebar user={user} />;\n}\n\nfunction Sidebar({ user }: { user: User }) {\n  return <UserMenu user={user} />;\n}\n\nfunction UserMenu({ user }: { user: User }) {\n  return <button>{user.name}</button>;\n}' },
        { type: 'text', title: 'Why drilling hurts', body: 'Drilling is not a bug; the app works. The cost shows up when you change things. Every middle component has a prop it does not care about, so reading its code becomes confusing. Renaming the prop, or changing its type, means edits in every file along the chain. The middle components are tightly coupled to their position in the tree, so reusing Sidebar elsewhere means supplying a user it never needed. And it is easy to forget to forward a prop after refactoring, leaving a component that silently receives undefined. Notice, though, that one or two levels of drilling is perfectly normal. Do not build a heavy solution for a tiny problem.' },
        { type: 'text', title: 'Fix 1: composition before Context', body: 'The first fix is often not Context at all. Since components can accept other components as props or as children, the parent that owns the data can build the final element itself and pass it down. Layout then needs no knowledge of users: it simply renders whatever it is given. This idea is called composition, and it is the same idea you met in Composition over inheritance. The data is used right where it lives, in App, and the intermediate components become simple containers. When composition is not enough, for example when many unrelated components far apart need the same value, the next tool is Context, which the following lessons cover.' },
        { type: 'code', language: 'tsx', caption: 'App now creates the UserMenu element itself and hands it to Layout as a prop called menu. Layout and Sidebar only place the element; they have no user prop at all. Adding an avatar to UserMenu now requires a change in one place.', code: 'function App() {\n  const user = { name: "Meera" };\n  return <Layout menu={<UserMenu user={user} />} />;\n}\n\nfunction Layout({ menu }: { menu: React.ReactNode }) {\n  return <Sidebar menu={menu} />;\n}\n\nfunction Sidebar({ menu }: { menu: React.ReactNode }) {\n  return <nav>{menu}</nav>;\n}\n\nfunction UserMenu({ user }: { user: { name: string } }) {\n  return <button>{user.name}</button>;\n}' },
        { type: 'example', title: 'Worked example: counting what must change', body: 'A shop app passes a theme string through five components: App, Page, Header, Nav and ThemeToggle. Only ThemeToggle uses it. Management asks you to rename the prop from theme to colorMode. You must edit five files and five type definitions, and if you miss one the page quietly uses undefined. Now compare the composition version. App builds <ThemeToggle theme={theme} /> and passes it as a toggle prop to Page, which hands it to Header, which places it inside Nav. Renaming the prop means touching only App and ThemeToggle. Two files instead of five, and the intermediate components stay unchanged. This is the practical test for any fix: count how many components must change when the data changes.' },
        { type: 'compare', title: 'Three ways to deliver data', columns: ['Prop drilling', 'Composition'], rows: [
          ['Who knows about the data', 'Every component on the path', 'Only the owner and the user'],
          ['Cost of renaming a prop', 'Edit each component on the path', 'Edit two components'],
          ['Best used when', 'The path is one or two levels long', 'Middle components are layout containers'],
        ] },
        { type: 'keyTerms', terms: [
          { term: 'Prop drilling', def: 'Passing a prop through components that do not use it, just to reach a deeper component.' },
          { term: 'Intermediate component', def: 'A component in the middle of the chain that only forwards props to its child.' },
          { term: 'Composition', def: 'Building UI by passing elements or children into components instead of passing raw data down.' },
          { term: 'Coupling', def: 'How much one component depends on the details of another; heavy drilling creates high coupling.' },
        ] },
        { type: 'callout', tone: 'warning', body: 'Do not reach for Context the moment a prop travels two levels. Context hides data flow and re-renders every consumer when the value changes; a short, visible chain of props is often clearer.' },
        { type: 'callout', tone: 'tip', body: 'If a middle component has a prop it never reads, only forwards, ask whether the parent can pass the finished element as children or a named prop instead.' },
        { type: 'summary', points: [
          'Prop drilling is forwarding a prop through components that do not use it, so that a deeply nested child can read it.',
          'It makes middle components cluttered and tightly coupled, and every rename or type change has to be repeated along the whole chain.',
          'Composition, passing a ready-made element through children or a named prop, often removes drilling without any new API.',
          'One or two levels of drilling is fine; use Context when many distant components need the same data.',
        ] },
      ],
    },
    quiz: [
      { type: 'mcq', q: 'In this tree, which components are only passing the prop along?\n\nfunction App() { return <A color="red" />; }\nfunction A({ color }) { return <B color={color} />; }\nfunction B({ color }) { return <C color={color} />; }\nfunction C({ color }) { return <p className={color}>Hi</p>; }', options: ['A and B', 'A and C', 'B and C', 'Only App'], answer: 0, why: 'A and B receive color and forward it unchanged. C is the only component that actually uses it, so A and B are the intermediate components in the drilling chain.', difficulty: 2 },
      { type: 'mcq', q: 'A prop called user is passed through four components and only the last one reads it. You rename it to account. How many components must you edit in the worst case?', options: ['All five, the owner, three middle components and the last one', 'Only the last one', 'Only the owner', 'None, because TypeScript renames the prop in every component for you'], answer: 0, why: 'Each component on the chain declares and forwards the prop by name, so a rename touches every one of them. This is the maintenance cost of drilling.', difficulty: 2 },
      { type: 'mcq', q: 'Layout receives sidebarMenu={<UserMenu user={user} />} from App and renders {sidebarMenu}. What has this changed?', options: ['Layout no longer needs a user prop', 'Layout now re-renders less often', 'UserMenu becomes a class component', 'user is now stored in global state'], answer: 0, why: 'The element is created by App, which owns user, so Layout only places it. That is composition, and it removes the user prop from Layout.', difficulty: 2 },
      { type: 'multi', q: 'Which of these are real drawbacks of long prop drilling chains?', options: ['Middle components receive props they never use', 'A rename or type change must be repeated along the chain', 'React refuses to render deeply nested components', 'Reusing a middle component elsewhere requires supplying unrelated props'], answers: [0, 1, 3], why: 'Drilling clutters and couples components, but React renders deep trees without trouble. The problem is maintenance, not capability.', difficulty: 2 },
      { type: 'truefalse', q: 'Passing a prop through one intermediate component to reach its grandchild is usually acceptable and does not require Context.', answer: true, why: 'Short chains are simple and make data flow visible. Heavier tools are worth it only when the chain becomes long or many components need the data.', difficulty: 2 },
      { type: 'fill', q: 'Passing a prop through several components that never use it, only to reach a deeply nested child, is called prop ____.', answer: 'drilling', accept: ['drill'], why: 'The prop “drills” through each layer of the tree. The name also hints at the problem: every layer is affected even though it does not need the data.', difficulty: 1 },
      { type: 'mcq', q: 'A Page component passes language to Header, which passes it to Nav, which passes it to LanguagePicker. Header and Nav are simple layout components. Which first step is the most proportionate fix?', options: ['Pass <LanguagePicker language={language} /> as an element prop from Page', 'Create a global variable', 'Move all components into one file', 'Store language in localStorage and read it in each component'], answer: 0, why: 'Composition keeps the data visible where it is owned and frees Header and Nav of the prop. Reach for Context only when composition no longer fits.', difficulty: 3 },
      { type: 'order', q: 'Order the steps of refactoring a drilled prop with composition.', items: ['Find the component that finally uses the prop', 'Have the owner create that element with the data', 'Pass the element down through children or a named prop', 'Delete the unused prop from the middle components'], why: 'You start from the consumer, build its element where the data lives, send the element down, and then remove the now pointless props.', difficulty: 2 },
    ],
    practice: [
      { type: 'mcq', q: 'A Dashboard passes the same notifications array to Header, which passes it to Toolbar, which passes it to Bell. Only Bell reads it. What is the best description of this code?', options: ['It is prop drilling through Header and Toolbar', 'It is a controlled component whose state lives in the Dashboard', 'It is a higher-order component', 'It is a memoisation problem caused by recreating the array every render'], answer: 0, why: 'Header and Toolbar only forward the prop, which is the definition of prop drilling.', difficulty: 1 },
      { type: 'mcq', q: 'A card component needs a title and a footer region whose content comes from the parent. Which signature avoids drilling the footer’s data into Card?', options: ['function Card({ title, footer }: { title: string; footer: React.ReactNode })', 'function Card({ title, footerData, footerFormat, footerTheme })', 'function Card({ title, userId, token, theme })', 'function Card({ everything }: { everything: any })'], answer: 0, why: 'Accepting a ready-made footer element means Card does not need to know what the footer shows or what data it needs.', difficulty: 2 },
      { type: 'mcq', q: 'In a drilled app, a developer adds a new field avatarUrl to user. Four components forward user as a whole object. How many need code changes to pass the new field along?', options: ['None of the forwarding components, only the producer and the consumer', 'All four, because each forwarding component receives the whole user object as a prop', 'Only the first one, since it receives user from the producer', 'Only the last one'], answer: 0, why: 'Because the whole user object is forwarded, the new field travels along automatically. Drilling individual fields would need edits everywhere. Still, the middle components remain coupled to the user type.', difficulty: 3 },
      { type: 'mcq', q: 'An app has a Settings page where a Save button, three levels down, needs saveSettings from the page. Only two components sit between them, both thin layout wrappers. What is the most reasonable choice?', options: ['Pass the function down as a prop, or pass the finished button as children', 'Build a Redux store with an action for every settings field', 'Add a Context for the whole app', 'Copy the function into every component that sits between the page and the button'], answer: 0, why: 'With a short chain of thin wrappers, props or composition keep the flow visible. A global tool would be more machinery than the problem needs.', difficulty: 2 },
      { type: 'mcq', q: 'A teammate says: “Prop drilling is a bug in React.” What is the best response?', options: ['It is a design trade-off; short chains are fine and long ones have fixes', 'Correct, React forbids passing props through more than one level', 'It only happens with class components and was removed by hooks in React 16.8', 'It only happens when using TypeScript'], answer: 0, why: 'Passing props down is how React normally works. Drilling only becomes a problem when the chain is long or the intermediate components are cluttered.', difficulty: 1 },
      { type: 'mcq', q: 'A Layout component is declared as function Layout({ children }: { children: React.ReactNode }) { return <main>{children}</main>; }. A page renders <Layout><Profile user={user} /></Layout>. Who needs a user prop?', options: ['Profile only, plus the owner of user', 'Layout and Profile, since both are in the chain', 'Layout only, because it renders the children', 'Neither'], answer: 0, why: 'The element is created in the owner and placed inside Layout through children. Layout never sees user, so no drilling occurs.', difficulty: 2 },
      { type: 'multi', q: 'Which approaches can reduce prop drilling?', options: ['Passing finished elements as children or named props', 'Providing the value with Context and reading it where needed', 'Adding more intermediate components so each does less', 'Moving the consumer component closer to the data owner in the tree'], answers: [0, 1, 3], why: 'Composition, Context and restructuring the tree all shorten or remove the chain. More wrapper components make the chain longer.', difficulty: 2 },
      { type: 'multi', q: 'In which of these cases is simple prop passing a good choice?', options: ['A Button needs a label from its direct parent', 'A grandchild needs one value and the child in between is a thin layout wrapper', 'Fifteen unrelated components across the page need the signed-in user', 'A list item needs an id and onSelect from the list'], answers: [0, 1, 3], why: 'Short, visible paths are best served by props. Data needed widely by distant components is the real use case for Context.', difficulty: 2 },
      { type: 'truefalse', q: 'When a middle component forwards a prop it never uses, changing that prop’s type forces edits in that middle component too.', answer: true, why: 'The middle component declares the prop in its own type, so a type change must be repeated there, which is part of the cost of drilling.', difficulty: 2 },
      { type: 'truefalse', q: 'Using Context is always a better solution than passing props through two components.', answer: false, why: 'Context hides data flow and re-renders every consumer on change. For one or two levels, plain props are simpler and more explicit.', difficulty: 2 },
      { type: 'fill', q: 'Passing a ready-made element through the children prop instead of raw data is an example of ____.', answer: 'composition', accept: ['component composition'], why: 'Composition lets the owner of the data build the element, so the components in between need not know the data exists.', difficulty: 1 },
      { type: 'code', q: 'Layout currently receives user and forwards it to Sidebar. Rewrite Layout so it accepts a menu prop of type React.ReactNode and renders it inside a <nav> element, instead of receiving user.', language: 'tsx', starter: 'function Layout({ user }: { user: User }) {\n  return <Sidebar user={user} />;\n}', solution: 'function Layout({ menu }: { menu: React.ReactNode }) {\n  return <nav>{menu}</nav>;\n}', checks: [{ label: 'Accepts a menu prop', pattern: String.raw`\{\s*menu\s*\}` }, { label: 'Renders menu inside nav', pattern: String.raw`<nav>\s*\{\s*menu\s*\}\s*</nav>` }, { label: 'No longer takes user', pattern: String.raw`^(?![\s\S]*\{\s*user\s*\})` }], why: 'Accepting the element means Layout no longer needs the data. The owner builds the element and passes it in.', difficulty: 2 },
    ],
  },
  'react-3': {
    summary: 'Lift state to the closest common parent when siblings must agree, and use Context when many distant components need the same value.',
    lesson: {
      minutes: 8,
      objectives: [
        'Lift state up to the closest common parent so two sibling components stay in sync',
        'Pass both a value and a setter down so a child can ask the parent to change state',
        'Read a value from Context with useContext inside a component',
        'Choose between lifting state and Context for a given situation',
      ],
      simple: 'When two components need the same data, move the state up to their nearest shared parent and pass it down as props. When the data is needed by many components far apart, put it in Context, like a noticeboard that any component below can read. Context re-renders all its readers when the value changes, so use it sensibly.',
      blocks: [
        { type: 'text', title: 'One source of truth', body: 'Imagine a temperature converter with two boxes: Celsius and Fahrenheit. When you type in one, the other must update. If each box keeps its own useState, they cannot know about each other and drift apart. React’s answer is to keep the number in only one place: the closest parent that contains both boxes. This is called lifting state up. The parent owns the state and passes the value down through props, plus a function to change it. Both boxes now display the same truth, because there is only one truth. It is the most important state-sharing technique in React, and it is simple.' },
        { type: 'analogy', body: 'Two friends keep separate diaries of the exam date, and one diary gets the date wrong. Better to pin a single timetable on the class noticeboard and let everyone read it. Lifting state up is that single timetable in a common room; Context, which we meet next, is a noticeboard that every room in the building can see.' },
        { type: 'code', language: 'tsx', caption: 'The state lives in Converter, the common parent. Each TempInput is a “controlled” child: it receives value and onChange as props and holds no state of its own. Typing in either box calls setCelsius, so Converter re-renders and both children show consistent values.', code: 'import { useState } from "react";\n\nfunction TempInput(props: {\n  label: string;\n  value: number;\n  onChange: (v: number) => void;\n}) {\n  return (\n    <label>\n      {props.label}\n      <input\n        type="number"\n        value={props.value}\n        onChange={(e) => props.onChange(Number(e.target.value))}\n      />\n    </label>\n  );\n}\n\nfunction Converter() {\n  const [celsius, setCelsius] = useState(100);\n  return (\n    <>\n      <TempInput label="°C" value={celsius} onChange={setCelsius} />\n      <TempInput\n        label="°F"\n        value={celsius * 9 / 5 + 32}\n        onChange={(f) => setCelsius((f - 32) * 5 / 9)}\n      />\n    </>\n  );\n}' },
        { type: 'text', title: 'The lifting recipe', body: 'Lifting state follows the same pattern every time. Find the components that need the data. Find their closest common parent, because anything higher up forces needless re-renders and drilling. Move the useState call into that parent. Pass the current value down as a prop and pass the setter, or a wrapper around it, as a callback prop such as onChange. This keeps the data flowing down and the events flowing up, the one-way flow described in Prop Drilling. Notice what is derived: the Fahrenheit value above is calculated from celsius, not stored separately, so the two can never disagree.' },
        { type: 'text', title: 'When lifting is not enough: Context', body: 'If the value is needed by components far apart, such as the colour theme for every button in the app, lifting would drill the prop through dozens of layers. Context solves this. You create a context with createContext, wrap part of the tree in its Provider with a value, and any component below can read the value with the useContext hook, no matter how deep. There is a price: when the Provider’s value changes, every component that reads that context re-renders, even if it only cares about a small part. Use Context for slow-changing, widely needed data such as theme, language or the signed-in user, not for something like text typed on every keystroke.' },
        { type: 'code', language: 'tsx', caption: 'createContext("dark") sets the default, used only when no Provider is above. App wraps Toolbar in a Provider whose value is "light", so Button, however deep, reads "light" through useContext without receiving any props.', code: 'import { createContext, useContext } from "react";\n\nconst Theme = createContext("dark");\n\nfunction App() {\n  return (\n    <Theme.Provider value="light">\n      <Toolbar />\n    </Theme.Provider>\n  );\n}\n\nfunction Toolbar() {\n  return <Button />;\n}\n\nfunction Button() {\n  const theme = useContext(Theme);\n  return <button className={theme}>Save</button>;\n}' },
        { type: 'example', title: 'Worked example: choosing a tool', body: 'A shopping app has three needs. First: a quantity stepper and a price label inside one product card must agree. Their closest common parent is the card, so lift the quantity into ProductCard and pass it to both. Second: the cart count in the header and an “Add” button two levels down in the product list. Their common parent is the App, which is close, so lifting cart state into App and passing props is fine. Third: the chosen language, read by nearly every label and button in 60 components. Drilling through every component is impractical, so put the language into a LanguageContext, provide it once at the top, and call useContext(LanguageContext) wherever needed. Rule of thumb: lift for a few nearby components, use Context for many distant ones.' },
        { type: 'compare', title: 'Lift state up versus Context', columns: ['Lift state up', 'Context'], rows: [
          ['Best for', 'A few nearby siblings', 'Data used deep and wide in the tree'],
          ['How data travels', 'Visible props', 'Provider and useContext'],
          ['Re-render cost', 'Only the parent and its children', 'All consumers when the value changes'],
          ['Example', 'Two linked temperature boxes', 'Theme, language, signed-in user'],
        ] },
        { type: 'keyTerms', terms: [
          { term: 'Lifting state up', def: 'Moving state from a child to the closest common parent so siblings can share it.' },
          { term: 'Single source of truth', def: 'Keeping each piece of data in exactly one place and deriving everything else from it.' },
          { term: 'Provider', def: 'A Context component that supplies a value to everything rendered inside it.' },
          { term: 'useContext', def: 'A hook that reads the value of the nearest Provider above the component.' },
        ] },
        { type: 'callout', tone: 'warning', body: 'Putting a fast-changing value, such as live text input, in one big context makes every consumer re-render on each keystroke. Keep such state local or lifted only as far as needed.' },
        { type: 'callout', tone: 'tip', body: 'Lift state up first. Introduce Context only when passing props has become tedious across many layers, and keep the shared data small.' },
        { type: 'summary', points: [
          'Siblings that must agree should share state held in their closest common parent, passed down as value and onChange props.',
          'Derive values from the single source of truth instead of storing copies, so they cannot get out of sync.',
          'Context supplies a value to any depth with a Provider, and useContext reads it without props.',
          'Every consumer re-renders when a Context value changes, so use it for slow-changing, widely needed data.',
        ] },
      ],
    },
    quiz: [
      { type: 'mcq', q: 'Two sibling components, Cart and Checkout, both need the same items array. Where should the useState for items live?', options: ['In each sibling separately', 'In a global variable', 'In their closest common parent', 'In localStorage only'], answer: 2, why: 'Lifting the state to the closest common parent gives both siblings one source of truth, passed down as props.', difficulty: 1 },
      { type: 'mcq', q: 'In the temperature converter, Celsius is stored in state and Fahrenheit is computed as celsius * 9 / 5 + 32. If celsius is 100, what does the Fahrenheit box show?', options: ['100', '132', '212', '37.8'], answer: 2, why: '100 × 9 / 5 = 180, and 180 + 32 = 212. The Fahrenheit value is derived, so it can never disagree with Celsius.', difficulty: 2 },
      { type: 'mcq', q: 'What does Button show?\n\nconst Theme = createContext("dark");\nfunction App() { return <Theme.Provider value="light"><Button /></Theme.Provider>; }\nfunction Button() { return <b>{useContext(Theme)}</b>; }', options: ['dark', 'undefined', 'light', 'An error'], answer: 2, why: 'useContext returns the value of the nearest Provider above the component, which is “light”. The default “dark” is used only when no Provider exists above.', difficulty: 2 },
      { type: 'multi', q: 'Which of these are good fits for Context rather than lifting state?', options: ['The colour theme read by dozens of components', 'The signed-in user shown in many places', 'Text typed into one search box and its result count next to it', 'The current language used by labels throughout the app'], answers: [0, 1, 3], why: 'Wide, slow-changing data suits Context. Two neighbouring components sharing a search term are better served by lifting state.', difficulty: 2 },
      { type: 'truefalse', q: 'When the value of a Context Provider changes, every component that calls useContext for that context re-renders.', answer: true, why: 'Consumers re-render whenever the provided value changes, which is why Context should hold slow-changing data.', difficulty: 2 },
      { type: 'fill', q: 'To read the current value of a context inside a function component, call the ____ hook.', answer: 'useContext', accept: ['use context'], why: 'useContext(SomeContext) returns the value from the nearest Provider above the calling component.', difficulty: 1 },
      { type: 'code', q: 'In a Badge component, read the current theme from ThemeContext and use it as the className of a <span>.', language: 'tsx', starter: 'function Badge() {\n  \n}', solution: 'function Badge() {\n  const theme = useContext(ThemeContext);\n  return <span className={theme}>New</span>;\n}', checks: [{ label: 'Calls useContext(ThemeContext)', pattern: String.raw`useContext\s*\(\s*ThemeContext\s*\)` }, { label: 'Uses it as the className', pattern: String.raw`className=\{\s*\w+\s*\}` }], why: 'useContext reads the nearest Provider’s value, so no props are needed.', difficulty: 2 },
      { type: 'mcq', q: 'A Counter component and a Total component are siblings under App. Counter has its own useState(0) and Total needs that number. What is the cleanest change?', options: ['Move the state to App and pass the count to both', 'Create a Context for one number', 'Call useState inside Total as well and keep both numbers synced by hand', 'Copy the number into localStorage'], answer: 0, why: 'App is the closest common parent. Lifting the state there and passing it down keeps one source of truth without extra machinery.', difficulty: 2 },
    ],
    practice: [
      { type: 'mcq', q: 'A Header and a Footer, both children of App, each hold their own useState for the selected language, and they disagree after the user changes it in Header. What is the root cause?', options: ['There are two separate copies of the state', 'useState cannot hold strings', 'Footer must use a class component to share state with Header', 'The Provider default is wrong'], answer: 0, why: 'Each useState call creates independent state. One shared copy, lifted to App or put in Context, removes the disagreement.', difficulty: 2 },
      { type: 'mcq', q: 'Here, typing in the input does not change what the label shows:\n\nfunction Form() {\n  const [name, setName] = useState("");\n  return <><Input /><Label name={name} /></>;\n}\nfunction Input() { const [v, setV] = useState(""); return <input value={v} onChange={e => setV(e.target.value)} />; }\n\nWhat is the fix?', options: ['Make Input call useContext to read the name from Label', 'Replace Label with a class component that reads the input', 'Pass name and setName to Input and remove its own state', 'Wrap Form in a Provider'], answer: 2, why: 'Input keeps a private copy of the text. Lifting means Form’s name state is the only one, passed to Input as value and onChange.', difficulty: 2 },
      { type: 'mcq', q: 'A Theme.Provider receives an object literal with mode and toggle as its value, written directly inside App’s render, and App re-renders often. What is the likely effect on consumers?', options: ['Nothing, because React compares objects by their content and skips renders', 'They stop receiving updates', 'They re-render each time because the object is new every render', 'They throw an error'], answer: 2, why: 'A new object literal is a new reference on every render, so React treats the value as changed. Memoise the value or keep it stable.', difficulty: 3 },
      { type: 'mcq', q: 'A Context default is createContext("dark"). A component calls useContext for it but there is no Provider above it. What does it receive?', options: ['"dark"', 'undefined', 'null', 'An error is thrown'], answer: 0, why: 'The default value is returned when no matching Provider is found above the component.', difficulty: 2 },
      { type: 'mcq', q: 'Which approach suits a “currently selected tab” shared only by a TabBar and a TabPanel under one Tabs parent?', options: ['A global store for the whole app', 'Context at the root of the app', 'Lifting the selected tab into Tabs', 'A browser cookie'], answer: 2, why: 'Two neighbouring components under one parent are the textbook case for lifting state up.', difficulty: 1 },
      { type: 'mcq', q: 'In the converter, Fahrenheit is stored in its own useState and Celsius in another, and you update both inside two onChange handlers. What bug risk does this create?', options: ['The two values can drift out of sync if one update is missed', 'The component cannot re-render', 'React blocks two related states in one component and throws a warning', 'Context is required'], answer: 0, why: 'Storing both creates two sources of truth. Computing one from the other removes the possibility of disagreement.', difficulty: 3 },
      { type: 'multi', q: 'Which statements about lifting state up are correct?', options: ['The state moves to the closest common parent of the components that need it', 'The parent passes the value and a change handler down as props', 'Each child should keep a copy of the state for speed', 'Derived values can be computed from the lifted state'], answers: [0, 1, 3], why: 'Lifting creates one owner and flows data down. Keeping extra child copies recreates the sync problem.', difficulty: 2 },
      { type: 'multi', q: 'Which of these will cause a component that calls useContext(LangContext) to re-render?', options: ['The Provider’s value changes', 'The component’s own state changes', 'A different, unrelated context changes', 'The parent re-renders it'], answers: [0, 1, 3], why: 'A consumer re-renders for its own state, a parent render and changes in contexts it reads. An unrelated context does not affect it.', difficulty: 3 },
      { type: 'truefalse', q: 'Lifting state up means that child components receive both the value and a function to request changes, rather than owning the state themselves.', answer: true, why: 'The parent owns the state; children get the value and a callback, so data flows down and events flow up.', difficulty: 1 },
      { type: 'truefalse', q: 'Context is the best place to store the text of a search box that changes on every keystroke and is shown beside it.', answer: false, why: 'Every consumer re-renders on each change, so frequent updates are costly. Keep fast-changing state local or lifted only as far as needed.', difficulty: 2 },
      { type: 'fill', q: 'When two sibling components must share state, you move it to their closest common ____.', answer: 'parent', accept: ['parent component', 'ancestor'], why: 'The closest common parent can pass state to both siblings with minimal prop passing.', difficulty: 1 },
      { type: 'order', q: 'Order the steps of lifting state up.', items: ['Identify the components that need the same data', 'Find their closest common parent', 'Move the useState call into that parent', 'Pass the value and a setter down as props'], why: 'You first discover who shares the data, find the owner, move the state there and connect the children through props.', difficulty: 1 },
    ],
  },
  'react-gen-12': {
    summary: 'The Context API (createContext, a Provider and useContext) delivers values to any depth, and is best wrapped in a provider component and a custom hook.',
    lesson: {
      minutes: 8,
      objectives: [
        'Create a context, provide a value and consume it with useContext',
        'Build a provider component that holds state and a custom hook that reads it safely',
        'Predict which value a consumer receives when providers are nested or missing',
        'Reduce unnecessary re-renders by memoising the context value or splitting contexts',
      ],
      simple: 'Context has three parts: createContext makes a channel, a Provider puts a value on it, and useContext reads the value anywhere below. In real apps we wrap these in our own provider component and a small custom hook, so the rest of the app never touches the raw context.',
      blocks: [
        { type: 'text', title: 'Three parts, one idea', body: 'In Context & lifting state you saw a short example. Here we look at the API properly. Context lets a component supply a value to everything rendered below it, however deep, without passing props through every layer. It has exactly three parts. createContext(defaultValue) creates the channel. A Provider component, with a value prop, sits above the components that need the data. The useContext hook, called in any component beneath, reads the current value. Typical uses are the colour theme, the interface language, the signed-in user and a shopping cart. These are things that many components need, and that change rarely.' },
        { type: 'analogy', body: 'Think of a college Wi-Fi network. The IT department sets one password at the main router (the Provider). Any phone, laptop or tablet inside the campus (a consumer) can join without being handed the password by every department in between. A phone outside the campus gets nothing and must fall back on whatever it had before, which is the default value.' },
        { type: 'text', title: 'Which value do you get?', body: 'useContext looks upwards from the component and returns the value of the nearest matching Provider. If providers are nested, the inner one wins inside its own subtree, which is handy for overriding a theme in one panel. If there is no Provider above the component at all, you receive the default value passed to createContext. Many teams pass undefined as the default and then throw a clear error in a custom hook, which catches the mistake of forgetting the Provider early, instead of silently using a made-up default. Remember also that a component reading a context re-renders when that context’s value changes.' },
        { type: 'code', language: 'tsx', caption: 'CartContext is created with undefined as the default. CartProvider owns the state and puts a value object on the context. useCart is the only way the app reads it, and it throws a helpful error if used outside the provider. Components call useCart() and never see createContext or useContext.', code: 'import { createContext, useContext, useState, useMemo, ReactNode } from "react";\n\ntype CartValue = { count: number; add: () => void };\n\nconst CartContext = createContext<CartValue | undefined>(undefined);\n\nexport function CartProvider({ children }: { children: ReactNode }) {\n  const [count, setCount] = useState(0);\n  const value = useMemo(\n    () => ({ count, add: () => setCount((c) => c + 1) }),\n    [count]\n  );\n  return <CartContext.Provider value={value}>{children}</CartContext.Provider>;\n}\n\nexport function useCart(): CartValue {\n  const ctx = useContext(CartContext);\n  if (!ctx) throw new Error("useCart must be used inside CartProvider");\n  return ctx;\n}' },
        { type: 'text', title: 'Keeping re-renders under control', body: 'Every time a Provider’s value changes, React re-renders all consumers. “Changes” means a different reference, not different contents. If the Provider writes an object literal such as { count, add } directly as its value, it creates a fresh object on every render of the provider component, so all consumers re-render whenever the provider’s parent re-renders, even if count did not change. useMemo, as above, keeps the same object until count changes. A second technique is splitting: keep rarely changing data (such as the add function) in one context and fast-changing data (such as count) in another, so components that only need the function do not re-render on every count change. Do these only when you notice a real slowdown; they are optimisations, not requirements.' },
        { type: 'code', language: 'tsx', caption: 'CartBadge reads count and re-renders when it changes. AddButton reads the same context here, so it would too; if you split the add function into its own context, it would not. The Provider wraps the whole app once, usually near the root.', code: 'function CartBadge() {\n  const { count } = useCart();\n  return <span>Cart ({count})</span>;\n}\n\nfunction AddButton() {\n  const { add } = useCart();\n  return <button onClick={add}>Add to cart</button>;\n}\n\nfunction App() {\n  return (\n    <CartProvider>\n      <CartBadge />\n      <AddButton />\n    </CartProvider>\n  );\n}' },
        { type: 'example', title: 'Worked example: nested providers and defaults', body: 'const Theme = createContext("dark"). App renders <Theme.Provider value="light"> around a Page. Inside Page there is a Sidebar wrapped in <Theme.Provider value="blue">, and a Footer outside the Sidebar, plus a Banner rendered above the outer Provider. Step by step. A button in Footer calls useContext(Theme): the nearest Provider above is the outer one, so it gets “light”. A button in Sidebar: the nearest Provider is the inner one, so “blue”. Banner is above every Provider, so it falls back to the default, “dark”. Now suppose the outer value changes to “paper”. Footer re-renders with “paper”. Sidebar’s value is still “blue”, because its own Provider shadows the outer one. This nearest-provider rule explains almost every context puzzle.' },
        { type: 'text', title: 'A note on React 19', body: 'In React 19 you can render the context object itself as the provider: <ThemeContext value="light"> instead of <ThemeContext.Provider value="light">. The older form still works. React 19 also adds the use function, which can read a context like useContext but may be called inside conditions. The meaning of the API is unchanged, so everything in this lesson applies to both styles.' },
        { type: 'keyTerms', terms: [
          { term: 'createContext', def: 'Creates a context object and sets the default value used when no Provider is above.' },
          { term: 'Provider', def: 'A component with a value prop that supplies the value to all components rendered inside it.' },
          { term: 'Consumer', def: 'Any component that reads a context, usually by calling useContext.' },
          { term: 'Default value', def: 'The value a consumer gets when no matching Provider exists above it.' },
          { term: 'Memoised value', def: 'A context value kept with useMemo so its reference stays the same between renders unless data changes.' },
        ] },
        { type: 'callout', tone: 'warning', body: 'Calling useContext in the same component that renders the Provider does not read that Provider’s value. It reads the one above the component. Read it in a child instead.' },
        { type: 'callout', tone: 'tip', body: 'Export only a provider component and a custom hook such as useCart. Hiding the raw context object gives you one place to add error checks, and lets you change how the value is stored later.' },
        { type: 'summary', points: [
          'Context has three parts: createContext, a Provider with a value, and useContext in consumers.',
          'A consumer receives the value of the nearest Provider above it, or the default value if there is none.',
          'Wrap a context in a provider component and a custom hook that throws if used outside the provider.',
          'Memoise the context value, or split rarely changing and frequently changing data into separate contexts, when re-renders become costly.',
        ] },
      ],
    },
    quiz: [
      { type: 'mcq', q: 'const Theme = createContext("dark"); A Banner is rendered above any Provider and calls useContext(Theme). What does it get?', options: ['"dark"', '"light"', 'undefined', 'It throws an error'], answer: 0, why: 'With no Provider above the component, useContext returns the default value given to createContext.', difficulty: 1 },
      { type: 'mcq', q: 'A page has <Theme.Provider value="light"> wrapping <Theme.Provider value="blue"> wrapping <Button />. Button calls useContext(Theme). What value does it get?', options: ['"light"', '"dark"', 'Both values as an array', '"blue"'], answer: 3, why: 'useContext returns the value of the nearest Provider above the component, so the inner one wins.', difficulty: 2 },
      { type: 'mcq', q: 'A Provider is written as value={{ count, add }} inside CartProvider. CartProvider’s parent re-renders but count has not changed. What happens to consumers?', options: ['They do not re-render because count is unchanged', 'They re-render because the object is new every time', 'They unmount', 'They receive undefined until the Provider mounts again'], answer: 1, why: 'The object literal is a new reference on each render of CartProvider, so React sees a changed value. useMemo keeps the reference stable.', difficulty: 3 },
      { type: 'multi', q: 'Which of these are parts of the Context API?', options: ['createContext', 'A Provider with a value prop', 'useContext', 'useReducerContext', 'A built-in useGlobalState hook'], answers: [0, 1, 2], why: 'createContext, a Provider and useContext are the three building blocks. The other two names do not exist in React.', difficulty: 1 },
      { type: 'truefalse', q: 'A custom hook such as useCart that throws an error when the context value is undefined helps you notice a missing Provider early.', answer: true, why: 'Without the check, a missing Provider would silently produce undefined values and confusing failures later.', difficulty: 2 },
      { type: 'fill', q: 'A consumer that has no matching Provider above it receives the ____ value passed to createContext.', answer: 'default', accept: ['initial', 'default value'], why: 'The argument to createContext is used only when there is no Provider above the component.', difficulty: 1 },
      { type: 'mcq', q: 'A useCart hook returns useContext(CartContext) and CartContext was created with createContext(undefined). Which line makes the hook safe to use in TypeScript and fail clearly outside a provider?', options: ['if (!ctx) throw new Error("useCart must be used inside CartProvider");', 'return ctx || {};', 'console.log(ctx);', 'ctx = {};'], answer: 0, why: 'Throwing narrows the type to a defined value and tells the developer exactly what is wrong when the Provider is missing.', difficulty: 2 },
      { type: 'order', q: 'Order the steps of setting up a context for a signed-in user.', items: ['Call createContext to make the channel', 'Write a provider component that holds the state', 'Wrap the app, or part of it, in that provider', 'Read the value in a component with useContext'], why: 'The channel must exist before a provider can supply it, and the provider must wrap the tree before a consumer can read from it.', difficulty: 1 },
    ],
    practice: [
      { type: 'mcq', q: 'In this code, what does Status show?\n\nconst Lang = createContext("en");\nfunction App() { return <Lang.Provider value="hi"><Status /></Lang.Provider>; }\nfunction Status() { return <p>{useContext(Lang)}</p>; }', options: ['hi', 'en', 'undefined', 'Nothing, it throws'], answer: 0, why: 'Status sits inside the Provider whose value is “hi”, so useContext returns “hi”, not the default “en”.', difficulty: 1 },
      { type: 'mcq', q: 'A component renders <Theme.Provider value="dark"><p>{useContext(Theme)}</p></Theme.Provider> but the context default is "light". What does the paragraph show?', options: ['dark', 'light', 'undefined', 'An error'], answer: 1, why: 'useContext in the component that renders the Provider reads the Provider above it, which does not exist, so it gets the default “light”.', difficulty: 3 },
      { type: 'mcq', q: 'A context holds { user, theme, cartCount } in one object, and a small Logo component that reads only theme re-renders each time cartCount changes. What is a reasonable fix?', options: ['Remove the Provider', 'Wrap Logo in useEffect', 'Split the data into separate contexts such as ThemeContext and CartContext', 'Use a class component for Logo, because class components never receive context updates'], answer: 2, why: 'Components re-render when the context they read changes. Separate contexts mean Logo no longer depends on cart updates.', difficulty: 3 },
      { type: 'mcq', q: 'In React 19, which JSX is a valid way to supply a value for ThemeContext?', options: ['<ThemeContext value="light">', '<ThemeContext.Value light>', '<useContext value="light">', '<Provider.ThemeContext value="light">'], answer: 0, why: 'React 19 lets you render the context object directly as the provider. The older ThemeContext.Provider form still works.', difficulty: 2 },
      { type: 'mcq', q: 'What does useMemo do in this provider?\n\nconst value = useMemo(() => ({ user, logout }), [user]);', options: ['Fetches the user from the server', 'Keeps the same object while user stays the same', 'Prevents the Provider from rendering at all', 'Stores user in localStorage'], answer: 1, why: 'useMemo returns the cached object until a dependency changes, so consumers do not re-render needlessly.', difficulty: 2 },
      { type: 'mcq', q: 'An app has AuthProvider at the root. A developer imports AuthContext directly in forty components and calls useContext(AuthContext). What improvement does a useAuth custom hook give?', options: ['It makes the context faster', 'It centralises the missing-provider check and hides the context object', 'It removes the need for a Provider because the hook creates its own context', 'It makes consumers immune to re-renders when the Provider value changes'], answer: 1, why: 'A hook gives one place for error handling and typing, and lets you change the implementation without editing forty components.', difficulty: 2 },
      { type: 'multi', q: 'Which statements are true about nested Providers of the same context?', options: ['The inner Provider’s value is used inside its own subtree', 'Components outside the inner Provider still see the outer value', 'The values are merged into one object', 'Each consumer reads the nearest Provider above it'], answers: [0, 1, 3], why: 'There is no merging. Each consumer simply uses the closest matching Provider above it.', difficulty: 2 },
      { type: 'multi', q: 'Which actions help reduce unnecessary re-renders caused by Context?', options: ['Memoising the Provider’s value with useMemo', 'Splitting fast-changing and slow-changing data into different contexts', 'Putting all application state into a single context', 'Keeping very frequently changing values, like live text input, out of Context'], answers: [0, 1, 3], why: 'Stable references, separated concerns and avoiding hot values reduce re-renders. One giant context makes every consumer depend on everything.', difficulty: 3 },
      { type: 'truefalse', q: 'Changing the default value passed to createContext updates every consumer that sits under a Provider.', answer: false, why: 'The default is used only when there is no Provider above. Consumers under a Provider always get that Provider’s value.', difficulty: 3 },
      { type: 'truefalse', q: 'A component that reads a context will re-render when that context’s Provider supplies a new value.', answer: true, why: 'That is how consumers stay up to date, and it is also why large, fast-changing values in context cost performance.', difficulty: 1 },
      { type: 'fill', q: 'In React 19, the ____ function can read a context like useContext but may also be called inside conditions.', answer: 'use', accept: ['use()', 'use hook'], why: 'The new use API reads promises and contexts and is the one exception to the “no conditional hooks” rule.', difficulty: 2 },
      { type: 'code', q: 'Write a custom hook useAuth that reads AuthContext with useContext and throws an Error if the value is undefined, otherwise returns it.', language: 'tsx', starter: 'function useAuth() {\n  \n}', solution: 'function useAuth() {\n  const ctx = useContext(AuthContext);\n  if (!ctx) throw new Error("useAuth must be used inside AuthProvider");\n  return ctx;\n}', checks: [{ label: 'Named useAuth', pattern: String.raw`(function|const)\s+useAuth\b` }, { label: 'Reads AuthContext with useContext', pattern: String.raw`useContext\s*\(\s*AuthContext\s*\)` }, { label: 'Throws when missing', pattern: String.raw`throw\s+new\s+Error` }, { label: 'Returns the value', pattern: String.raw`return\s+\w+` }], why: 'A guarded hook gives a clear error when the provider is missing and a defined value everywhere else.', difficulty: 2 },
    ],
  },
  'react-gen-13': {
    summary: 'A higher-order component is a function that takes a component and returns an enhanced component, adding shared behaviour around it.',
    lesson: {
      minutes: 8,
      objectives: [
        'Write a higher-order component that wraps another component and forwards its props',
        'Explain why an HOC must be created outside render and must pass props through',
        'Compare an HOC with a custom hook for sharing the same behaviour',
        'Recognise real-world HOCs such as React.memo and Redux’s connect',
      ],
      simple: 'A higher-order component, or HOC, is a function that takes a component and gives you back a new, upgraded component. For example, withAuth(Dashboard) returns a Dashboard that first checks whether you are logged in. It is a way to reuse the same wrapper behaviour for many components, although hooks now do this job more simply.',
      blocks: [
        { type: 'text', title: 'Functions that upgrade components', body: 'You already know that a function can take another function as an argument and return a new one. A higher-order component, shortened to HOC, applies the same idea to components. It is a function that receives a component and returns a new component that wraps the original and adds something: a loading spinner, a login check, logging, or extra props. The name follows the usual convention of starting with “with”, as in withAuth or withLoading. An HOC is not a React feature; it is a pattern built on ordinary JavaScript and the composition ideas from Composition over inheritance. Before hooks existed, it was the main way to share logic between components, and you will still meet it in older code bases and libraries.' },
        { type: 'analogy', body: 'Think of a phone cover. You hand over your phone and get back the same phone, still working in the same way, but now protected, and perhaps with a card holder attached. The cover does not change the phone. The HOC does the same: you give it a component, and you receive a wrapped version that behaves like the original and has extra abilities.' },
        { type: 'code', language: 'tsx', caption: 'withLoading takes any component C that needs the original props P, and returns a new component. The new component accepts those props plus an isLoading flag. While loading it shows text; otherwise it renders C and forwards every other prop with the spread operator.', code: 'import type { ComponentType } from "react";\n\nfunction withLoading<P extends object>(C: ComponentType<P>) {\n  function WithLoading(props: P & { isLoading: boolean }) {\n    const { isLoading, ...rest } = props;\n    if (isLoading) return <p>Loading…</p>;\n    return <C {...(rest as P)} />;\n  }\n  WithLoading.displayName = "withLoading(" + (C.displayName || C.name) + ")";\n  return WithLoading;\n}\n\nfunction PriceList({ items }: { items: number[] }) {\n  return <ul>{items.map((p) => <li key={p}>₹{p}</li>)}</ul>;\n}\n\nconst PriceListWithLoading = withLoading(PriceList);\n// <PriceListWithLoading isLoading={false} items={[499, 899]} />' },
        { type: 'text', title: 'Rules for writing a good HOC', body: 'Four habits keep HOCs healthy. First, pass props through: the wrapper must forward every prop it does not use, otherwise the wrapped component loses its inputs. Second, do not change the original component: return a new one instead of editing the one you were given. Third, never create an HOC inside a component’s render. Each render would produce a brand-new component type, and from Reconciliation you know that a different type makes React unmount the old tree and mount a new one, destroying state each time. Always call the HOC once, at module level. Fourth, set a displayName so React DevTools shows withLoading(PriceList) instead of an anonymous component.' },
        { type: 'text', title: 'Where HOCs show up, and why hooks replaced many of them', body: 'React.memo is an HOC: it takes a component and returns a version that skips re-rendering when props are unchanged. Redux’s older connect function and React Router’s old withRouter were HOCs that injected data into props. They work, but they have costs. Stacking several of them, withAuth(withTheme(withLoading(Page))), creates deep wrapper layers in DevTools, sometimes called wrapper hell. Props arrive from several wrappers, so it is hard to see where each one came from, and names can collide. A custom hook such as useAuth() gives the same logic with a plain function call and no extra layers, which is why hooks are the default today. HOCs remain useful for wrapping behaviour around whole components, such as redirecting away from protected pages.' },
        { type: 'example', title: 'Worked example: protecting a page with withAuth', body: 'Goal: only a logged-in user may see Dashboard. Step 1: write function withAuth(C) that returns a component. Step 2: inside the returned component, read the user (here from a useAuth hook). Step 3: if there is no user, return <Navigate to="/login" /> or a message; otherwise return <C {...props} />. Step 4: outside every component, write const ProtectedDashboard = withAuth(Dashboard). Step 5: route to ProtectedDashboard. Result: Dashboard stays focused on its own job and knows nothing about logins; the same withAuth wraps Settings and Profile with one line each. The same behaviour as a hook would be: const user = useAuth(); if (!user) return <Navigate />; inside each page, which means three copies of that check. The HOC removes the copies, while the hook keeps the logic visible inside each component. Both are valid; choose by whether the behaviour belongs around the component or inside it.' },
        { type: 'compare', title: 'Higher-order component versus custom hook', columns: ['HOC', 'Custom hook'], rows: [
          ['Shape', 'Function from component to component', 'Function that returns values to a component'],
          ['Can change what is rendered', 'Yes, it can replace the whole output', 'Only the component itself decides'],
          ['Where it appears', 'Around the component, in the tree', 'Inside the component body'],
          ['Typical cost', 'Extra wrapper layers and prop collisions', 'Must be called inside each component'],
        ] },
        { type: 'keyTerms', terms: [
          { term: 'Higher-order component', def: 'A function that takes a component and returns a new, enhanced component.' },
          { term: 'Wrapper component', def: 'The component returned by an HOC that renders the original one inside it.' },
          { term: 'Prop forwarding', def: 'Passing the wrapper’s unused props on to the wrapped component, usually with the spread operator.' },
          { term: 'displayName', def: 'A name React DevTools shows for a component; HOCs set it to describe the wrapping.' },
        ] },
        { type: 'callout', tone: 'warning', body: 'Never write const Enhanced = withLoading(List) inside a component body. A new component type is created on every render, so React throws away and rebuilds the subtree, losing its state and focus each time.' },
        { type: 'callout', tone: 'fact', body: 'React.memo(Component) is a higher-order component that ships inside React itself. It returns a new component that skips re-rendering when its props have not changed.' },
        { type: 'summary', points: [
          'A higher-order component is a function that takes a component and returns a new component wrapping it.',
          'Good HOCs forward all props, leave the original component untouched, are created at module level and set a displayName.',
          'HOCs can change what is rendered around a component, such as redirecting, but stacking many creates wrapper layers and prop collisions.',
          'Custom hooks now handle most logic sharing; HOCs remain in libraries and for whole-component wrapping.',
        ] },
      ],
    },
    quiz: [
      { type: 'mcq', q: 'What does withAuth(Dashboard) return?', options: ['A new component that wraps Dashboard', 'A boolean', 'A string of HTML', 'The same Dashboard, changed in place'], answer: 0, why: 'An HOC takes a component and returns a new component that renders the original inside it, with extra behaviour. It does not edit the original.', difficulty: 1 },
      { type: 'mcq', q: 'An HOC renders <C /> without forwarding props, and the wrapped Product component shows “undefined” for its name. Which fix is correct?', options: ['Convert Product to a class', 'Render <C {...props} />', 'Add a key prop', 'Call the HOC inside render'], answer: 1, why: 'The wrapper must pass its props on to the wrapped component. Spreading props forwards everything the wrapper does not consume itself.', difficulty: 2 },
      { type: 'mcq', q: 'A developer writes this inside a component:\n\nfunction Page() {\n  const List = withLoading(RawList);\n  return <List isLoading={false} />;\n}\n\nWhat goes wrong?', options: ['Nothing, wrapping inside render is a recommended pattern because it keeps props fresh', 'RawList can no longer use props', 'A new component type is created each render, so the list remounts and loses state', 'withLoading runs only once and caches itself'], answer: 2, why: 'A new function means a new component type every render, so React unmounts and mounts the subtree each time. Create the enhanced component outside render.', difficulty: 3 },
      { type: 'multi', q: 'Which of these are well-known examples or uses of higher-order components?', options: ['React.memo', 'Redux’s connect function in older code', 'useState', 'A withAuth wrapper that redirects when logged out'], answers: [0, 1, 3], why: 'memo, connect and withAuth all take a component and return another. useState is a hook, not an HOC.', difficulty: 2 },
      { type: 'truefalse', q: 'A custom hook can often share the same logic as an HOC without adding an extra component layer to the tree.', answer: true, why: 'A hook runs inside the component, so no wrapper component is added, which is a main reason hooks replaced many HOCs.', difficulty: 2 },
      { type: 'fill', q: 'By convention an HOC’s name carries a conventional short prefix; a wrapper that adds a login check is named ____Auth.', answer: 'with', accept: ['with…'], why: 'The “with” prefix signals that the function adds something to the component passed in.', difficulty: 1 },
      { type: 'code', q: 'Write an HOC withLogger that takes a component C and returns a new component that calls console.log("render") and then renders C with all the props it received.', language: 'tsx', starter: 'function withLogger(C: React.ComponentType<any>) {\n  \n}', solution: 'function withLogger(C: React.ComponentType<any>) {\n  return function Logged(props: any) {\n    console.log("render");\n    return <C {...props} />;\n  };\n}', checks: [{ label: 'Returns a function (component)', pattern: String.raw`return\s+(function|\(|\w+\s*=>)` }, { label: 'Logs something', pattern: String.raw`console\.log\s*\(` }, { label: 'Spreads props into C', pattern: String.raw`<\s*C\s+\{\s*\.\.\.\s*\w+\s*\}\s*/?>` }], why: 'An HOC returns a new component that does its extra work and then renders the original with every prop forwarded.', difficulty: 2 },
      { type: 'match', q: 'Match each pattern problem with its cause.', pairs: [['Wrapper hell', 'Many stacked HOC layers'], ['Lost state on every render', 'HOC created inside render'], ['Missing props in wrapped component', 'Wrapper did not forward props'], ['Hard-to-read DevTools tree', 'No displayName on the wrapper']], why: 'Each symptom comes from a specific HOC mistake, which is why the rules are to forward props, create the HOC once, and name the wrapper.', difficulty: 2 },
    ],
    practice: [
      { type: 'mcq', q: 'Given const Safe = withErrorBoundary(Chart), where is the best place to write that line?', options: ['At module level, outside any component', 'Inside Chart’s render', 'Inside a useEffect callback that runs after mount', 'Inside an onClick handler'], answer: 0, why: 'The enhanced component should be created once so its identity stays stable between renders.', difficulty: 2 },
      { type: 'mcq', q: 'An HOC wraps a component but needs to add a user prop. Which return is correct?', options: ['return <C user={user} />', 'return <C {...props} user={user} />', 'return C(props, user)', 'return props.user'], answer: 1, why: 'Forward the wrapper’s own props and add the new one, so the wrapped component receives everything.', difficulty: 2 },
      { type: 'mcq', q: 'DevTools shows a tree of nested components called Anonymous, Anonymous, Anonymous, Page. Which small change in the HOC code makes it easier to debug?', options: ['Add a key to every element', 'Set displayName on the returned component', 'Switch to class components so each one gets a name', 'Pass fewer props'], answer: 1, why: 'displayName gives the wrapper a readable name such as withAuth(Page) in DevTools and error messages.', difficulty: 1 },
      { type: 'mcq', q: 'You need the same “redirect to /login when no user” check on twenty page components. Which pattern avoids twenty copies of the check while keeping pages focused?', options: ['Duplicate the check in each page', 'Wrap each page with a withAuth HOC', 'Store the check in localStorage', 'Use a global variable'], answer: 1, why: 'An HOC can wrap behaviour around many components, replacing their output with a redirect, without touching their code.', difficulty: 2 },
      { type: 'mcq', q: 'Two stacked HOCs both inject a prop called data, as in withUsers(withOrders(List)). What is the likely problem?', options: ['A name collision, one prop silently overwrites the other', 'React throws a syntax error', 'Both props are merged into an array that the list must flatten', 'Neither wrapper renders'], answer: 0, why: 'Props from several wrappers share one namespace, so same-named props collide. Hooks avoid this because you name each result yourself.', difficulty: 3 },
      { type: 'mcq', q: 'Which statement about React.memo is correct?', options: ['It is a higher-order component that skips re-rendering when props are unchanged', 'It is a hook that stores state', 'It forces a component to re-render each time its parent updates, even if props match', 'It works only with class components'], answer: 0, why: 'memo takes a component and returns an enhanced one, which is exactly an HOC.', difficulty: 1 },
      { type: 'multi', q: 'Which are recommended practices when writing an HOC?', options: ['Forward the props the wrapper does not use', 'Return a new component instead of modifying the original', 'Call the HOC inside the wrapped component’s render', 'Set a displayName for debugging'], answers: [0, 1, 3], why: 'Forward props, avoid mutation and name the wrapper. Calling the HOC in render creates a new component every time and destroys state.', difficulty: 2 },
      { type: 'multi', q: 'Compared with HOCs, what advantages do custom hooks typically offer?', options: ['No extra wrapper component in the tree', 'No prop-name collisions because you name the returned values', 'They can replace the entire rendered output of a component', 'The data source is visible inside the component'], answers: [0, 1, 3], why: 'Hooks run inside the component, so wrapper layers and collisions disappear. Replacing a component’s output wholesale is something an HOC does more naturally.', difficulty: 3 },
      { type: 'truefalse', q: 'An HOC should modify the component it receives by adding methods directly to it.', answer: false, why: 'HOCs should compose: return a new wrapper component and leave the original unchanged, so it can still be used on its own.', difficulty: 2 },
      { type: 'truefalse', q: 'Wrapping a component in an HOC adds an extra component to the rendered tree.', answer: true, why: 'The wrapper component renders the original one inside it, which is why many stacked HOCs deepen the tree.', difficulty: 1 },
      { type: 'fill', q: 'Wrapping several HOCs around one component can produce a deep tree that developers call wrapper ____.', answer: 'hell', accept: ['hell.'], why: 'Each HOC adds a layer in DevTools, making it hard to trace where props and behaviour come from.', difficulty: 1 },
      { type: 'order', q: 'Order what happens when <ProtectedDashboard /> renders, where ProtectedDashboard = withAuth(Dashboard) and the user is logged in.', items: ['The wrapper component function runs', 'It reads the current user', 'It sees that a user exists', 'It renders Dashboard with the forwarded props'], why: 'The wrapper runs first, checks its condition, and only then renders the wrapped component.', difficulty: 2 },
    ],
  },
  'react-gen-14': {
    summary: 'A render prop is a function prop the component calls with its state, so it shares logic while the caller controls the UI.',
    lesson: {
      minutes: 8,
      objectives: [
        'Write a component that shares state by calling a function prop with that state',
        'Use a render prop through either a named prop or the children function form',
        'Predict what renders given a component that calls its render prop with specific values',
        'Compare render props with custom hooks and choose the simpler tool',
      ],
      simple: 'A render prop is a prop whose value is a function. The component does the work, such as tracking the mouse position or loading data, and then calls your function with the result so that you decide what to draw. The component owns the logic and you own the look.',
      blocks: [
        { type: 'text', title: 'Sharing logic, leaving the UI open', body: 'Some components know how to do something but should not decide what it looks like. A MouseTracker knows where the pointer is. A DataLoader knows when the data has arrived. One screen wants to show coordinates as text, another wants a glowing circle that follows the cursor. If the component hard-codes its own output, it can serve only one of them. The render props pattern solves this: the component takes a function as a prop, and calls that function with its internal state to get the JSX to display. The component keeps the behaviour and the caller supplies the rendering. The pattern is a close cousin of the Higher-Order Components you just studied, and was widely used before hooks.' },
        { type: 'analogy', body: 'A photographer’s studio has equipment, lighting and a skilled operator. You arrive with a frame design of your own, and the studio fits your frame around the picture it takes. The studio does the technical work; you decide how the result looks. A render prop is your frame design handed to the component.' },
        { type: 'code', language: 'tsx', caption: 'MouseTracker owns the x and y state and a mousemove listener. Instead of rendering anything itself, it calls render(position). The caller passes a function that receives the position and returns JSX. The same MouseTracker could be reused with a completely different function.', code: 'import { useEffect, useState, type ReactNode } from "react";\n\ntype Pos = { x: number; y: number };\n\nfunction MouseTracker({ render }: { render: (pos: Pos) => ReactNode }) {\n  const [pos, setPos] = useState<Pos>({ x: 0, y: 0 });\n  useEffect(() => {\n    const move = (e: MouseEvent) => setPos({ x: e.clientX, y: e.clientY });\n    window.addEventListener("mousemove", move);\n    return () => window.removeEventListener("mousemove", move);\n  }, []);\n  return <>{render(pos)}</>;\n}\n\nfunction App() {\n  return (\n    <MouseTracker render={(p) => <p>Mouse at {p.x}, {p.y}</p>} />\n  );\n}' },
        { type: 'text', title: 'The children-as-a-function form', body: 'The prop does not have to be called render. Any prop holding a function works, and a popular variation uses the children prop itself: <MouseTracker>{(pos) => <p>{pos.x}</p>}</MouseTracker>. Inside the component, you call children(pos) instead of render(pos), and give children the type (pos: Pos) => ReactNode. This reads naturally because the function sits where the output will appear. Both forms are the same pattern: the key is that the prop is a function that returns what to render, and the component calls it, usually with its state or helpers as arguments. Do not confuse this with an ordinary event callback such as onClick: a render prop returns JSX for React to display, an event callback does work in response to an event.' },
        { type: 'example', title: 'Worked example: a Toggle that shares on and off', body: 'We want a Toggle that tracks an on/off boolean and lets callers draw anything. Step 1: Toggle keeps const [on, setOn] = useState(false). Step 2: it renders children({ on, toggle: () => setOn(o => !o) }). Step 3: one caller passes a function that returns a <button> labelled “Lights: ON” or “Lights: OFF”, using on and toggle. Step 4: another caller, in a settings page, uses the same Toggle to draw a checkbox. Both reuse the same state logic, and neither duplicates it. Result: if the first caller renders {on ? "ON" : "OFF"} and the user clicks once, on becomes true and the label shows “Lights: ON”. The state lives in Toggle, but the markup lives in each caller. As a bonus, two Toggles on one page keep independent states, because each is its own component instance.' },
        { type: 'code', language: 'tsx', caption: 'Toggle calls children with an object containing the current state and a function to flip it. The caller destructures what it needs. Notice the type of children: it is a function, not a ReactNode.', code: 'import { useState, type ReactNode } from "react";\n\ntype ToggleApi = { on: boolean; toggle: () => void };\n\nfunction Toggle({ children }: { children: (api: ToggleApi) => ReactNode }) {\n  const [on, setOn] = useState(false);\n  return <>{children({ on, toggle: () => setOn((o) => !o) })}</>;\n}\n\nfunction Lights() {\n  return (\n    <Toggle>\n      {({ on, toggle }) => (\n        <button onClick={toggle}>Lights: {on ? "ON" : "OFF"}</button>\n      )}\n    </Toggle>\n  );\n}' },
        { type: 'text', title: 'Costs and the modern alternative', body: 'Render props have two weaknesses. First, nesting: using three of them together creates a pyramid of functions inside JSX, which people call callback hell. Second, performance: an inline arrow function is a new function on every render, so a child wrapped in React.memo that receives it as a prop will re-render anyway, as the next module on memoisation explains. Today a custom hook such as useMouse() or useToggle() gives the same logic without any nesting: const pos = useMouse(). Prefer a hook for sharing logic. Render props still make sense when the component needs to control where and how many times your content is rendered, for example a list component that calls your function for every row, or a virtualised list that renders only visible items.' },
        { type: 'compare', title: 'Render prop versus custom hook', columns: ['Render prop', 'Custom hook'], rows: [
          ['How you use it', 'Pass a function that returns JSX', 'Call the hook inside your component'],
          ['Readability with several uses', 'Nested functions in JSX', 'Flat lines at the top of the component'],
          ['Controls where UI appears', 'Yes, the component decides when to call', 'No, your component decides'],
          ['Typical use today', 'Lists, virtualisation, library APIs', 'Sharing stateful logic'],
        ] },
        { type: 'keyTerms', terms: [
          { term: 'Render prop', def: 'A prop whose value is a function that the component calls to find out what to render.' },
          { term: 'Children as a function', def: 'The variation in which the children prop is the render function.' },
          { term: 'Inversion of control', def: 'The component runs the logic and calls back into code you wrote to produce the UI.' },
          { term: 'Callback hell', def: 'Deeply nested functions that become hard to read, such as stacked render props.' },
        ] },
        { type: 'callout', tone: 'warning', body: 'Do not put a render function in the position of a normal child value. children={(x) => …} must be called by the component. If the component renders {children} without calling it, React cannot display a function and prints a warning.' },
        { type: 'callout', tone: 'tip', body: 'If a component’s only job is to share logic and you find yourself writing {(value) => …} around a whole page, try extracting a custom hook first.' },
        { type: 'summary', points: [
          'A render prop is a function prop that returns JSX; the component calls it with its state, so the caller chooses how the data looks.',
          'The function can arrive in a named prop such as render, or as children, and must be called by the component.',
          'Several render props nest awkwardly and inline functions break memoisation of children.',
          'Custom hooks usually share logic more cleanly; render props fit cases where the component decides when and how often your UI is drawn.',
        ] },
      ],
    },
    quiz: [
      { type: 'mcq', q: 'What does this render?\n\nfunction Greeter({ render }) { return <div>{render("Asha")}</div>; }\n<Greeter render={(n) => <b>Hi {n}</b>} />', options: ['Hi Asha in bold', 'Nothing, render is not allowed', 'The text render', 'An error, because render is not called'], answer: 0, why: 'Greeter calls render with “Asha”, and the function returns <b>Hi Asha</b>, which is what appears inside the div.', difficulty: 1 },
      { type: 'mcq', q: 'A Counter component renders {children} but the caller passes <Counter>{(n) => <p>{n}</p>}</Counter>. What is the problem?', options: ['children is a function and must be called, as in children(count)', 'p cannot hold numbers', 'Counter needs to be a class component to accept a function as its child', 'The caller must pass a key'], answer: 0, why: 'React cannot render a function as a child. The component has to call it with the data and render the JSX it returns.', difficulty: 2 },
      { type: 'mcq', q: 'In Toggle, children is called as children({ on, toggle }). The caller writes {({ on, toggle }) => <button onClick={toggle}>{on ? "ON" : "OFF"}</button>}. After the first click, what does the button show?', options: ['OFF', 'ON', 'Nothing', 'An error'], answer: 1, why: 'on starts false, shows OFF, and toggle flips it to true. Toggle re-renders and calls the function again, so the label becomes ON.', difficulty: 2 },
      { type: 'multi', q: 'Which of these describe the render props pattern?', options: ['The component calls a function prop to decide what to render', 'The component can pass its state as arguments to that function', 'The function prop must be named render', 'The caller controls the UI while the component controls the logic'], answers: [0, 1, 3], why: 'Any prop name works, including children. The essence is a function prop returning JSX, called with the component’s data.', difficulty: 2 },
      { type: 'truefalse', q: 'A custom hook can often share the same stateful logic as a render prop without nesting functions inside JSX.', answer: true, why: 'Calling useMouse() inside a component gives the position directly, avoiding the pyramid of nested functions.', difficulty: 1 },
      { type: 'fill', q: 'A prop whose value is a function that returns JSX, called by the receiving component to decide what to draw, is a ____ prop.', answer: 'render', accept: ['render prop'], why: 'The name comes from the fact that the function’s job is to render something, using data from the component.', difficulty: 1 },
      { type: 'mcq', q: 'A parent passes render={(p) => <Chart data={p} />} inline to a React.memo component on every render. Why might the memoised child still re-render each time?', options: ['memo only works on class components', 'The inline arrow function is a new reference on each parent render', 'render props cannot be memoised at all by design', 'Chart is not exported'], answer: 1, why: 'memo compares props by reference. A function created inline is a new value every render, so the comparison fails. Stabilise it with useCallback or move it out.', difficulty: 3 },
      { type: 'code', q: 'Write a Toggle component that keeps an on boolean in state (start false) and renders children called with the object { on, toggle }, where toggle flips on.', language: 'tsx', starter: 'function Toggle({ children }: { children: (api: { on: boolean; toggle: () => void }) => React.ReactNode }) {\n  \n}', solution: 'function Toggle({ children }: { children: (api: { on: boolean; toggle: () => void }) => React.ReactNode }) {\n  const [on, setOn] = useState(false);\n  return <>{children({ on, toggle: () => setOn((o) => !o) })}</>;\n}', checks: [{ label: 'Keeps state with useState', pattern: String.raw`useState\s*\(\s*false\s*\)` }, { label: 'Calls children as a function', pattern: String.raw`children\s*\(` }, { label: 'Passes on and toggle', pattern: String.raw`children\s*\(\s*\{[^}]*on[^}]*toggle|children\s*\(\s*\{[^}]*toggle[^}]*on` }, { label: 'Flips the value', pattern: String.raw`!\s*\w+` }], why: 'The component owns the state and calls the function prop with it, so each caller can render its own UI.', difficulty: 3 },
    ],
    practice: [
      { type: 'mcq', q: 'A DataLoader component calls props.render({ loading, data }). A caller wants a spinner while loading and a list afterwards. Where should that if-else live?', options: ['Inside the function the caller passes as render', 'Inside React itself, in the reconciler that calls render', 'In index.html, where the root element is declared', 'In a CSS file'], answer: 0, why: 'The caller decides how to display each state, so the loading check belongs in the function that returns the JSX.', difficulty: 2 },
      { type: 'mcq', q: 'Which signature fits a component that calls its children as a function with a number?', options: ['children: ReactNode', 'children: (count: number) => ReactNode', 'children: number', 'children: string[]'], answer: 1, why: 'A render-function child is typed as a function that takes the data and returns something React can render.', difficulty: 2 },
      { type: 'mcq', q: 'A list component is declared as function List({ items, renderItem }) { return <ul>{items.map(i => <li key={i.id}>{renderItem(i)}</li>)}</ul>; }. Why is a render prop a good fit here?', options: ['The list decides when and how often to call renderItem, while the caller decides how each row looks', 'Lists cannot be rendered without it', 'It makes keys unnecessary', 'It stops re-renders'], answer: 0, why: 'The list controls the repetition and layout, and the render prop customises the content of each row, a classic use for the pattern.', difficulty: 2 },
      { type: 'mcq', q: 'MouseTracker renders {render(pos)} and the caller passes render={(p) => <p>{p.x}</p>}. The mouse is at x = 120. What text appears?', options: ['120', 'p.x', 'x', '0'], answer: 0, why: 'The component calls render with the position object, and the returned paragraph displays its x property, 120.', difficulty: 1 },
      { type: 'mcq', q: 'Three render props are nested to combine mouse, window size and theme. What is the most useful refactor?', options: ['Replace them with custom hooks called at the top of the component', 'Add more nesting levels', 'Move everything into one class component with a large render method', 'Use global variables'], answer: 0, why: 'Hooks give the same data as flat variables, removing the pyramid of nested functions.', difficulty: 2 },
      { type: 'mcq', q: 'How does a render prop differ from an onClick callback?', options: ['A render prop returns JSX for React to display, a click callback runs in response to an event', 'They are identical', 'onClick returns JSX', 'A render prop cannot receive any arguments, while an onClick callback always receives the event object'], answer: 0, why: 'Both are function props, but the render function’s return value becomes part of the UI, whereas an event handler’s return value is ignored.', difficulty: 2 },
      { type: 'multi', q: 'Which statements about the children-as-a-function form are correct?', options: ['The component calls children(...) to get the JSX', 'The caller writes a function between the opening and closing tags', 'The component can render {children} directly without calling it', 'It is the same idea as a named render prop'], answers: [0, 1, 3], why: 'It is a render prop supplied through children. Rendering a function without calling it does not work.', difficulty: 2 },
      { type: 'multi', q: 'Which are drawbacks of the render props pattern?', options: ['Nested functions can make JSX hard to read', 'Inline functions create new references each render', 'It cannot access component state', 'It can hamper React.memo on children that receive the function'], answers: [0, 1, 3], why: 'Nesting and unstable function identity are the main costs. Render props can access state; that is the point.', difficulty: 3 },
      { type: 'truefalse', q: 'The prop that holds the render function must be named render for React to recognise the pattern.', answer: false, why: 'React does not care about the name. Any prop, including children, can hold the function as long as the component calls it.', difficulty: 1 },
      { type: 'truefalse', q: 'Two Toggle components using a render prop on the same page keep separate on/off states.', answer: true, why: 'Each Toggle instance has its own useState, so toggling one does not affect the other.', difficulty: 2 },
      { type: 'fill', q: 'Rewriting the logic of a render-prop component as a function like useMouse() gives you a custom ____.', answer: 'hook', accept: ['hooks'], why: 'A custom hook shares the same stateful logic and returns the values directly.', difficulty: 1 },
      { type: 'order', q: 'Order what happens when the pointer moves in the MouseTracker example.', items: ['The mousemove listener fires', 'setPos stores the new coordinates', 'MouseTracker re-renders', 'The render function is called with the new position'], why: 'State changes first, which triggers a re-render, and then the component calls the function prop with the updated values.', difficulty: 2 },
    ],
  },
  'react-gen-15': {
    summary: 'Compound components are a set of components that share hidden state, usually through context, so callers can arrange the parts freely.',
    lesson: {
      minutes: 8,
      objectives: [
        'Explain how a parent component and its child parts share state without prop drilling',
        'Build a Tabs component from a context provider, a guarded hook and attached sub-components',
        'Predict what a compound component renders for a given set of ids and default state',
        'Choose between compound components and a single component with many configuration props',
      ],
      simple: 'Compound components are a team of components that only make sense together, like <select> and <option> in HTML. The parent keeps the state and quietly shares it through context, so each child part can read it. You then arrange the parts yourself instead of passing a long list of props.',
      blocks: [
        { type: 'text', title: 'Components that work as a team', body: 'In plain HTML, <select> and <option> are a pair. An <option> on its own does nothing useful, and a <select> with no options is empty. Yet you never pass the list of choices as one big attribute. You simply nest the parts and the browser connects them. Compound components bring the same idea to React. A Tabs component and its Tab and Panel parts are written to be used together, and they share state behind the scenes. The result is an API that reads like markup: you can see the structure, reorder the parts and add your own elements between them.' },
        { type: 'analogy', body: 'Think of a board game box. The board, dice and pieces each do one small job, and none of them is a game alone. The rule book is not printed on every piece. Instead, everyone at the table shares the same rules, and any piece can be placed anywhere on the board. In a compound component, the parent is the shared rule book and the parts are the pieces.' },
        { type: 'text', title: 'The old way: one component, many props', body: 'Without this pattern you would write <Tabs titles={["Notes", "Quiz"]} panels={[<Notes />, <Quiz />]} />. It looks tidy until someone wants an icon on one tab, a badge on another, or a disabled tab. Each wish becomes a new prop such as showIcon, iconPosition or disabledTabs, and the component grows into a long list of options that nobody remembers. Compound components avoid this. The caller writes the parts as children and decorates each one directly, so the parent needs no extra props.' },
        { type: 'text', title: 'How the parts share state', body: 'There are three pieces. First, the parent owns the state with useState and wraps its children in a context provider, which you met in the Context API module. Second, each child part calls useContext to read that state or call its setter. Third, a small custom hook, as in the Custom Hooks module, wraps useContext and throws a clear error when the context is missing, so a Tab used outside Tabs fails loudly. Because context reaches every depth, a Tab still works when wrapped in a <div> or another component. Older code used React.Children.map and cloneElement to push props into children, but that only reaches direct children and breaks as soon as you wrap one.' },
        { type: 'code', language: 'tsx', caption: 'TabsContext holds the active id and its setter. useTabs reads the context and throws if the parts are used outside Tabs. Tabs owns the state with useState and provides it. Tabs.Tab shows a button that sets the active id when clicked. Tabs.Panel renders its children only when its id is the active one. Assigning Tab and Panel to Tabs is just attaching properties to a function, so callers can write <Tabs.Tab>.', code: 'import { createContext, useContext, useState, type ReactNode } from "react";\nconst TabsContext = createContext<{ active: string; setActive: (id: string) => void } | null>(null);\n\nfunction useTabs() {\n  const ctx = useContext(TabsContext);\n  if (!ctx) throw new Error("Use Tab parts inside <Tabs>");\n  return ctx;\n}\nfunction Tabs({ defaultId, children }: { defaultId: string; children: ReactNode }) {\n  const [active, setActive] = useState(defaultId);\n  return <TabsContext.Provider value={{ active, setActive }}>{children}</TabsContext.Provider>;\n}\nTabs.Tab = function Tab({ id, children }: { id: string; children: ReactNode }) {\n  const { active, setActive } = useTabs();\n  return <button aria-selected={active === id} onClick={() => setActive(id)}>{children}</button>;\n};\nTabs.Panel = function Panel({ id, children }: { id: string; children: ReactNode }) {\n  return useTabs().active === id ? <div>{children}</div> : null;\n};' },
        { type: 'example', title: 'Worked example: using the Tabs', body: 'Here is how a caller writes the screen, followed by what happens. Step 1: Tabs starts with active = "notes" because of defaultId. Step 2: both Panel parts read the context. The notes Panel sees "notes" === "notes" and shows “Read chapter 3.”. The quiz Panel sees "quiz" !== "notes" and returns null. Step 3: the learner clicks the Quiz tab, so setActive("quiz") runs. Step 4: Tabs re-renders, the provider’s value changes, and every part that called useTabs re-renders. Step 5: now the quiz Panel shows “Ten questions.” and the notes Panel returns null. The caller never passed active to any child.' },
        { type: 'code', language: 'tsx', caption: 'The caller nests the parts like HTML. The ids link each Tab to its Panel. The caller could put the Panel parts above the Tab buttons or wrap a Tab in a <div> and nothing would break.', code: '<Tabs defaultId="notes">\n  <Tabs.Tab id="notes">Notes</Tabs.Tab>\n  <Tabs.Tab id="quiz">Quiz</Tabs.Tab>\n  <Tabs.Panel id="notes">Read chapter 3.</Tabs.Panel>\n  <Tabs.Panel id="quiz">Ten questions.</Tabs.Panel>\n</Tabs>' },
        { type: 'compare', title: 'Configuration props versus compound components', columns: ['One component with props', 'Compound components'], rows: [['Calling code', 'A single tag with arrays and options', 'Nested parts that read like markup'], ['Layout control', 'Fixed by the component', 'Caller reorders or wraps parts freely'], ['Adding a feature', 'Add another prop', 'Add or style a part'], ['Hidden cost', 'A long, growing props list', 'Parts fail outside the parent unless guarded']] },
        { type: 'keyTerms', terms: [{ term: 'Compound components', def: 'A parent and child parts designed to be used together, sharing hidden state.' }, { term: 'Implicit state', def: 'State shared through context, so callers never pass it to each part.' }, { term: 'Static property', def: 'A component attached as a property of another, such as Tabs.Panel.' }, { term: 'Guard hook', def: 'A custom hook that reads context and throws if no provider is above it.' }] },
        { type: 'callout', tone: 'warning', body: 'Do not rely on React.Children.map plus cloneElement to inject props. It only touches direct children, so wrapping a Tab in a <div> silently breaks it. Use context instead.' },
        { type: 'callout', tone: 'tip', body: 'Start createContext with null and throw in the hook. A clear message like “Use Tab parts inside <Tabs>” saves minutes of confusing undefined errors. For big trees, wrap the provider value in useMemo.' },
        { type: 'summary', points: ['Compound components are a parent plus parts, like <select> and <option>, that share state without the caller passing it.', 'The parent owns the state and provides it through context; each part reads it with a guarded custom hook.', 'Context works at any depth, so callers can wrap or reorder parts, unlike cloneElement which reaches only direct children.', 'Prefer this pattern when a single component would need many layout-related props.'] },
      ],
    },
    quiz: [
      { type: 'mcq', q: 'Given the Tabs code from the lesson, what happens here?\n\nfunction App() { return <Tabs.Tab id="notes">Notes</Tabs.Tab>; }', options: ['It throws “Use Tab parts inside <Tabs>”', 'It renders a button that does nothing', 'It renders nothing and logs no error', 'It uses defaultId as a fallback'], answer: 0, why: 'There is no provider above, so useContext returns null and the guard in useTabs throws its error. It does not render a dead button.', difficulty: 2 },
      { type: 'mcq', q: 'A team has <Tabs titles={[…]} panels={[…]} /> and keeps adding props like showIcon and iconPosition. What is the main benefit of switching to compound components?', options: ['State no longer needs to live anywhere', 'Callers decorate each part directly instead of needing new props', 'The parts re-render less often than before', 'Context becomes unnecessary for sharing'], answer: 2, why: 'With nested parts, an icon is just another child placed inside a Tab. The parent API stops growing. Performance is not the point.', difficulty: 2 },
      { type: 'mcq', q: 'In the lesson’s code, what does the line Tabs.Panel = function Panel(…) {…} accomplish?', options: ['It attaches a component as a property so <Tabs.Panel> works', 'It registers the panel with React’s router', 'It makes Panel share state with Tabs automatically', 'It stops Panel from re-rendering'], answer: 1, why: 'Functions are objects, so you can attach a property. It is only naming. The state sharing comes from the context and useTabs, not from the assignment.', difficulty: 2 },
      { type: 'multi', q: 'Which statements about compound components are correct?', options: ['The parent usually owns the shared state', 'Children can read that state through context', 'Every child must receive active as a prop', 'Callers can reorder or wrap the parts'], answers: [0, 1, 3], why: 'State lives in the parent and flows through context, so no child needs a prop for it. That is also why wrapping and reordering are safe.', difficulty: 2 },
      { type: 'truefalse', q: 'In a compound Tabs component built with context, every Tab and Panel must be given the active id as a prop from the caller.', answer: false, why: 'The parts read the active id from context through useTabs. The caller only passes each part’s own id.', difficulty: 1 },
      { type: 'fill', q: 'Compound components usually share their hidden state through React ____.', answer: 'context', accept: ['Context', 'the Context API', 'useContext'], why: 'The parent provides the state with a context provider and each part reads it with useContext.', difficulty: 1 },
      { type: 'code', q: 'Write a Panel component that reads active from useTabs() and renders its children inside a <div> only when active equals its id prop. Otherwise it should render null.', language: 'tsx', starter: 'function Panel({ id, children }: { id: string; children: React.ReactNode }) {\n  \n}', solution: 'function Panel({ id, children }: { id: string; children: React.ReactNode }) {\n  const { active } = useTabs();\n  return active === id ? <div>{children}</div> : null;\n}', checks: [{ label: 'Calls useTabs()', pattern: String.raw`useTabs\s*\(\s*\)` }, { label: 'Compares active with id', pattern: String.raw`active\s*===?\s*id|id\s*===?\s*active` }, { label: 'Returns null otherwise', pattern: String.raw`null|&&` }], why: 'Panel reads the shared state from the hook, compares the ids and either returns its content or null. Returning null renders nothing.', difficulty: 2 },
      { type: 'order', q: 'Order what happens after a learner clicks the Quiz tab in the Tabs example.', items: ['Tab’s onClick calls setActive("quiz")', 'Tabs state changes to "quiz"', 'Tabs re-renders and the provider value changes', 'Tab and Panel parts that use useTabs re-render', 'The quiz Panel now shows its children'], why: 'The click updates state in the parent, the new context value reaches every consumer, and each part decides what to show.', difficulty: 3 },
    ],
    practice: [
      { type: 'mcq', q: 'A developer writes <Card><Card.Header>Hi</Card.Header></Card> but forgets the line Card.Header = Header. What is the most likely result?', options: ['React falls back to a plain <div>', 'Context is created automatically for it', 'An error saying the element type is undefined', 'Header renders but loses its styles'], answer: 3, why: 'Card.Header is undefined, and React cannot render an undefined element type, so it throws an invalid element type error.', difficulty: 2 },
      { type: 'mcq', q: 'A Tab is wrapped like <Tabs><div className="bar"><Tabs.Tab id="a">A</Tabs.Tab></div></Tabs>. What happens?', options: ['It still works because context reaches nested components', 'It breaks because Tab is no longer a direct child', 'It works only if the div is given a key', 'It works only after cloneElement is added'], answer: 1, why: 'Context is available to every descendant of the provider at any depth. Only a cloneElement approach depends on direct children.', difficulty: 2 },
      { type: 'mcq', q: 'Tabs has defaultId="quiz" and Panel parts with ids "notes" and "quiz", each showing its id as text. What does the screen show before any click?', options: ['notes and quiz together', 'quiz', 'notes', 'Nothing until a tab is clicked'], answer: 2, why: 'active starts as "quiz", so only the Panel with id "quiz" passes the comparison and the other returns null.', difficulty: 2 },
      { type: 'mcq', q: 'Why does useTabs check if (!ctx) throw new Error(…) instead of just returning the context?', options: ['The context starts as null and a clear error beats a crash on destructuring', 'React requires every hook to throw once', 'useContext returns undefined whenever state changes', 'It stops the provider from re-rendering'], answer: 0, why: 'With null as default, a part used outside Tabs would fail on destructuring with a confusing message. The guard also narrows the TypeScript type.', difficulty: 3 },
      { type: 'mcq', q: 'A developer builds an Accordion that needs a Header and a Body per item, and callers sometimes want custom wrappers around them. Which design fits best?', options: ['One component with a layout string such as "wide"', 'Global variables that store the open item', 'Accordion.Item parts that read open state from context', 'A prop called items holding arrays of titles and bodies'], answer: 3, why: 'Parts that read shared state from context let callers nest and wrap freely, without the parent knowing the layout.', difficulty: 2 },
      { type: 'mcq', q: 'A learner reads the Tabs code and asks which two hooks from earlier modules power it. Which pair is right?', options: ['useState and useContext', 'useReducer and useLayoutEffect', 'useMemo and useRef only', 'useId and useTransition'], answer: 1, why: 'The parent uses useState for the data and provides it, and the parts read it with useContext, usually via a custom hook.', difficulty: 1 },
      { type: 'multi', q: 'Consider a long props list versus nested parts. Which are real benefits of the compound approach?', options: ['Callers can reorder or wrap parts', 'The parent needs fewer layout props', 'Parts work outside the parent with no provider', 'Markup structure is visible in the JSX'], answers: [0, 1, 3], why: 'The structure is explicit and flexible. Parts still need the parent, because the shared state comes from its provider.', difficulty: 2 },
      { type: 'multi', q: 'A developer’s Tabs component misbehaves. Which mistakes could be the cause?', options: ['Rendering a Tab outside Tabs without a guard in the hook', 'Forgetting to assign Tabs.Panel = Panel', 'Wrapping a Tab in a <div> inside Tabs', 'Giving a Panel an id that no Tab uses'], answers: [0, 1, 3], why: 'A missing provider or missing property fails outright, and a Panel with an unmatched id never shows. A wrapper div is fine with context.', difficulty: 3 },
      { type: 'truefalse', q: 'If a Tab is wrapped in a <div> inside Tabs, it stops reading the shared state when that state is shared through context.', answer: false, why: 'Context reaches every descendant of the provider, so extra wrapper elements do not matter.', difficulty: 2 },
      { type: 'fill', q: 'In the call <Tabs.Panel id="a">, Panel is attached to the Tabs function as a static ____.', answer: 'property', accept: ['properties', 'static property', 'member'], why: 'Functions are objects in JavaScript, so you can attach other components to them as properties.', difficulty: 1 },
      { type: 'match', q: 'Match each part of the Tabs example (“Tabs”, “Tab”, “Panel”, “useTabs”) to its job.', pairs: [['Tabs', 'Owns the state and provides the context'], ['Tab', 'Button that calls setActive with its id'], ['Panel', 'Shows content when its id is active'], ['useTabs', 'Reads context and throws if it is missing']], why: 'Each part has one small responsibility, and all of them depend on the same shared context.', difficulty: 2 },
      { type: 'mcq', q: 'A team’s <Menu> component now has props for icons, dividers, groups and shortcuts, and callers cannot remember them all. Which refactor best helps?', options: ['Turn the props into global CSS classes', 'Split into Menu.Item, Menu.Divider and Menu.Group parts', 'Merge all props into one object named config', 'Add default values for every prop'], answer: 2, why: 'Parts let callers place each feature where it belongs, with no hidden config surface. A config object only hides the same complexity.', difficulty: 3 },
    ],
  },
  'react-gen-16': {
    summary: 'A controlled input shows a value held in React state, while an uncontrolled input keeps its own text in the DOM.',
    lesson: {
      minutes: 8,
      objectives: [
        'Write a controlled text input using value and onChange',
        'Read an uncontrolled input with defaultValue and a ref, or with FormData',
        'Diagnose the “changing an uncontrolled input to be controlled” warning and fix it',
        'Choose between controlled and uncontrolled inputs for a given form',
      ],
      simple: 'Every form field has a current text. In a controlled input, React state owns that text and the input just shows it. In an uncontrolled input, the browser owns the text and you ask for it only when you need it, using a ref or FormData.',
      blocks: [
        { type: 'text', title: 'Who owns the text in the box?', body: 'When a learner types an email into a sign-up form, someone has to remember what was typed. There are two answers. The browser can remember it, as it did before React existed. Or your React component can remember it in state. A field where React state is the single source of truth is called a **controlled input**. A field where the browser’s own DOM keeps the text is called an **uncontrolled input**. Both are valid. The choice decides how easily you can validate, format or reset the text, and how much your component re-renders while the user types.' },
        { type: 'analogy', body: 'Imagine a whiteboard in a classroom. In the controlled style, the teacher (React state) holds the master copy of the notes, and after every word a student says, the teacher rewrites the board. The board always matches the master copy. In the uncontrolled style, students write directly on the board, and the teacher walks over and reads it only when needed, for example at the end of class.' },
        { type: 'text', title: 'Controlled: value plus onChange', body: 'A controlled input has two props that work as a pair. The value prop tells the input what text to show. The onChange prop runs on every keystroke, so you can copy the new text from event.target.value into state. React then re-renders and passes the new state back as value. The loop is: user types, onChange fires, setState runs, the component renders, the input shows the state. If you give value but forget onChange, nothing you type appears, because React keeps resetting the box to the unchanged state, and React warns you that the field is read-only. Because the text lives in state, you can change it on the way in. For example, converting to upper case or blocking digits is just one line inside onChange.' },
        { type: 'text', title: 'Uncontrolled: defaultValue plus a ref', body: 'An uncontrolled input skips state. You give it a starting text with defaultValue, and after that the browser handles every keystroke. To read the text you attach a ref (from the useRef hook) and look at ref.current.value when you need it, such as inside a submit handler. React never re-renders while the user types, which is cheap and simple. Note the word “default”: defaultValue is used only on the first render. Changing it later does not change what the user sees. Also note that you set the starting text only through defaultValue, not through value, because value would make the input controlled.' },
        { type: 'code', language: 'tsx', caption: 'NameControlled keeps the text in state: value shows it, and onChange copies each keystroke into state. NameUncontrolled gives the browser the starting text with defaultValue and reads the text only on click through inputRef.current?.value. Only the controlled one re-renders on every keystroke.', code: 'import { useRef, useState } from "react";\n\nfunction NameControlled() {\n  const [name, setName] = useState("");\n  return <input value={name} onChange={(e) => setName(e.target.value)} />;\n}\n\nfunction NameUncontrolled() {\n  const inputRef = useRef<HTMLInputElement>(null);\n  const save = () => alert(inputRef.current?.value);\n  return (\n    <>\n      <input defaultValue="Asha" ref={inputRef} />\n      <button onClick={save}>Save</button>\n    </>\n  );\n}' },
        { type: 'example', title: 'Worked example: the sneaky warning', body: 'A developer writes const [city, setCity] = useState(); and then <input value={city} onChange={(e) => setCity(e.target.value)} />. Step 1: on the first render city is undefined, so React treats the input as uncontrolled. Step 2: the learner types “P”, setCity("P") runs and city becomes a string. Step 3: now value is defined, so React sees the same input switch to controlled and prints “A component is changing an uncontrolled input to be controlled”. Step 4: the fix is to start with an empty string, useState(""). The input then stays controlled from the first render. The same warning appears in reverse if value becomes undefined or null later, for example when an API field is missing. Use value={user.email ?? ""} to keep it controlled.' },
        { type: 'text', title: 'Forms in React 19: actions and FormData', body: 'Modern React gives uncontrolled inputs a neat partner. In React 19 you can pass a function to a form’s action prop: <form action={save}>. When the form is submitted, React calls save with a FormData object holding every named field, so you read formData.get("email") with no refs and no state. Each input needs a name attribute for this to work. After a successful action, React also resets uncontrolled fields for you. This suits simple forms. Use controlled inputs when you need live feedback while typing.' },
        { type: 'compare', title: 'Controlled versus uncontrolled', columns: ['Controlled', 'Uncontrolled'], rows: [['Where the text lives', 'React state', 'The DOM'], ['Initial text', 'The initial state value', 'defaultValue'], ['Reading the text', 'Read the state any time', 'ref.current.value or FormData'], ['Re-renders while typing', 'Yes, on every keystroke', 'No'], ['Best for', 'Live validation, formatting, dependent fields', 'Simple forms, file inputs, quick prototypes']] },
        { type: 'keyTerms', terms: [{ term: 'Controlled input', def: 'An input whose value prop comes from React state and is updated in onChange.' }, { term: 'Uncontrolled input', def: 'An input that keeps its own value in the DOM, read later with a ref or FormData.' }, { term: 'defaultValue', def: 'The starting text of an uncontrolled input; changing it after the first render has no effect.' }, { term: 'FormData', def: 'A browser object holding the named fields of a form, passed to a React 19 form action.' }, { term: 'File input', def: 'An input of type file, always uncontrolled because only the user can set its value.' }] },
        { type: 'callout', tone: 'warning', body: 'Never give an input value without onChange, and never start a controlled input as undefined. Use useState("") and value={x ?? ""}. For a checkbox, the controlled prop is checked, not value.' },
        { type: 'callout', tone: 'fact', body: 'An <input type="file"> is always uncontrolled. For security, a page cannot set which file is chosen. Read the selection from event.target.files in onChange or from a ref, never through a value prop.' },
        { type: 'callout', tone: 'tip', body: 'Pick controlled when the UI reacts to each keystroke, for example a disabled Submit button, a character counter or a live search. Pick uncontrolled when you only need the text at submit time.' },
        { type: 'summary', points: ['A controlled input pairs value with onChange so React state is the single source of truth.', 'An uncontrolled input uses defaultValue for its start text and a ref or FormData to read it later.', 'Starting a controlled input as undefined triggers the “uncontrolled to controlled” warning; start with an empty string.', 'File inputs are always uncontrolled, and React 19 form actions hand you FormData for named fields.'] },
      ],
    },
    quiz: [
      { type: 'mcq', q: 'A learner types into this field but no text appears. What is the cause?\n\nconst [email, setEmail] = useState("");\nreturn <input value={email} />;', options: ['useState("") cannot hold typed text', 'The value is fixed and no onChange updates the state', 'React ignores value on input elements', 'The input needs a ref before it accepts text'], answer: 1, why: 'A controlled input shows exactly what its value prop says. With no onChange to update the state, the text stays "" and React warns that the field is read-only.', difficulty: 2 },
      { type: 'mcq', q: 'A form has <input defaultValue="Asha" />. The learner types “Ravi”, then the parent re-renders because of unrelated state. What does the input show?', options: ['Asha, because defaultValue is applied again', 'An empty box until a new key is pressed', 'An error, because defaultValue cannot change', 'Ravi, because the DOM keeps the typed text'], answer: 3, why: 'defaultValue is used only on the first render. After that the browser owns the text, so an unrelated re-render does not reset it.', difficulty: 2 },
      { type: 'mcq', q: 'React warns “A component is changing an uncontrolled input to be controlled” for this code. Which change removes it?\n\nconst [city, setCity] = useState();\n<input value={city} onChange={(e) => setCity(e.target.value)} />', options: ['Use useState("") so value is always a string', 'Replace value with defaultValue and keep onChange', 'Wrap the input in a <form> element', 'Call setCity inside a useEffect on mount'], answer: 0, why: 'On the first render city is undefined, so React treats the input as uncontrolled. Starting at an empty string keeps it controlled throughout.', difficulty: 2 },
      { type: 'multi', q: 'Which of these inputs are uncontrolled?', options: ['<input defaultValue="Hi" ref={r} />', '<input value={text} onChange={setT} />', '<input type="file" />', '<input name="email" /> read by a form action'], answers: [0, 2, 3], why: 'Uncontrolled inputs keep their text in the DOM, whether read by a ref, by FormData or through files. Only the value plus onChange pair makes an input controlled.', difficulty: 2 },
      { type: 'truefalse', q: 'You can make an <input type="file"> controlled by passing it a value prop that holds the chosen file name.', answer: false, why: 'Only the user can pick a file, so a file input is always uncontrolled. Read event.target.files in onChange or use a ref.', difficulty: 2 },
      { type: 'fill', q: 'To read the current text of an uncontrolled input inside a click handler, attach a ____ to it using the useRef hook.', answer: 'ref', accept: ['ref object', 'useRef', 'reference'], why: 'A ref gives direct access to the DOM node, so inputRef.current.value returns whatever the user has typed so far.', difficulty: 1 },
      { type: 'code', q: 'Write a component Search that renders a controlled text input. Keep the text in state called query (initially an empty string), pass it as value, and update it in onChange from event.target.value.', language: 'tsx', starter: 'function Search() {\n  \n}', solution: 'function Search() {\n  const [query, setQuery] = useState("");\n  return <input value={query} onChange={(e) => setQuery(e.target.value)} />;\n}', checks: [{ label: 'Creates state with useState', pattern: String.raw`useState\s*(<[^>]*>)?\s*\(` }, { label: 'Binds value to the state', pattern: String.raw`value\s*=\s*\{\s*query\s*\}` }, { label: 'Updates state from the event', pattern: String.raw`onChange\s*=\s*\{[^}]*target\.value` }], why: 'A controlled input needs both halves: value from state, and onChange writing event.target.value back into that state.', difficulty: 2 },
      { type: 'order', q: 'Order what happens when a learner types one character into a controlled input.', items: ['The browser fires a change event on the input', 'onChange runs and calls setState with event.target.value', 'React re-renders the component with the new state', 'The input receives the new state as its value prop'], why: 'Typing triggers onChange, which updates state; the render then feeds that state back into the input as value.', difficulty: 2 },
    ],
    practice: [
      { type: 'mcq', q: 'In React 19, this form is submitted with “a@b.in” in the field. What does save receive?\n\nasync function save(formData: FormData) { console.log(formData.get("email")); }\n<form action={save}><input name="email" /></form>', options: ['null, because the input has no ref', 'The string “a@b.in”, read by its name attribute', 'A synthetic event holding the field', 'undefined, because the input is uncontrolled'], answer: 1, why: 'A form action receives FormData keyed by each field’s name attribute, so no state or ref is needed. Without the name, get("email") would return null.', difficulty: 2 },
      { type: 'mcq', q: 'A learner types 10 characters into a controlled input and into an uncontrolled input inside the same parent. About how many times does the parent re-render because of this typing?', options: ['10 for the controlled one, 0 for the uncontrolled one', '0 for both, since the DOM handles typing', '10 for both, since each keystroke triggers a render', '1 for the controlled one, when typing ends'], answer: 0, why: 'Each keystroke calls setState in the controlled version, which re-renders. The uncontrolled input updates only the DOM.', difficulty: 2 },
      { type: 'mcq', q: 'What does the input show after the learner types “abc”?\n\n<input value={t} onChange={(e) => setT(e.target.value.toUpperCase())} />', options: ['abc, since the DOM text is untouched', 'Nothing, because toUpperCase is not allowed', 'Abc, with only the first letter changed', 'ABC, because the state is what the input displays'], answer: 3, why: 'A controlled input always shows its value prop. Since onChange stores the upper-case text, state and display both become ABC.', difficulty: 2 },
      { type: 'mcq', q: 'A developer writes <input type="file" value={file} onChange={pick} /> and sees an error. What is the right fix?', options: ['Drop value and read event.target.files in onChange', 'Initialise file as an empty string, not null', 'Switch value to defaultValue, which file inputs allow', 'Add a ref so React can set the file name'], answer: 0, why: 'File inputs are always uncontrolled; a page cannot set the chosen file. Read the selection from event.target.files.', difficulty: 2 },
      { type: 'mcq', q: 'A sign-up form must disable the Submit button until the password has at least 8 characters, updating on every keystroke. Which approach fits best?', options: ['An uncontrolled input read once with a ref when the form is submitted', 'A controlled input, so the length is available in render', 'defaultValue with a longer minimum', 'A file input with an accept filter'], answer: 1, why: 'The button depends on the current text during rendering, so the text must be in state. A controlled input provides this.', difficulty: 2 },
      { type: 'mcq', q: 'A controlled checkbox is written <input type="checkbox" value={agreed} onChange={…} />. Why does it not behave as expected?', options: ['Checkboxes can only be uncontrolled', 'onChange is not supported on checkboxes', 'A checkbox is controlled with checked, not value', 'agreed must be a string rather than a boolean'], answer: 2, why: 'For checkboxes and radios, the controlled prop is checked with a boolean, and onChange reads event.target.checked.', difficulty: 2 },
      { type: 'mcq', q: 'An uncontrolled form has a Clear button. The learner has typed in several fields. Which approach clears them all without state?', options: ['Call setState("") for every field', 'Pass a new defaultValue to every input so the fields refresh', 'Re-create the useRef objects', 'Call reset() on the form element through a ref'], answer: 3, why: 'The DOM form element has a reset() method that restores every uncontrolled field to its default value. Changing defaultValue later does nothing.', difficulty: 3 },
      { type: 'multi', q: 'A team is building a quick contact form and weighing uncontrolled inputs. Which of these are good reasons to choose them?', options: ['The form only needs its values when submitted', 'You want to avoid a re-render on each keystroke', 'You need to format the text as the user types', 'You are using a React 19 form action with FormData'], answers: [0, 1, 3], why: 'Uncontrolled inputs suit submit-time reads and cheap typing. Live formatting needs the text in state, which means a controlled input.', difficulty: 2 },
      { type: 'multi', q: 'A developer reviews four fields in a profile form. Which of these inputs are controlled?', options: ['<input value={n} onChange={e => setN(e.target.value)} />', '<input defaultValue={n} ref={r} />', '<input type="checkbox" checked={on} onChange={toggle} />', '<textarea value={bio} onChange={setBio} />'], answers: [0, 2, 3], why: 'A value or checked prop driven by state, with an onChange, makes the field controlled. defaultValue with a ref is the uncontrolled pair.', difficulty: 2 },
      { type: 'truefalse', q: 'A parent renders <input defaultValue={user.name} /> and later user.name changes from “Asha” to “Ravi”. The text displayed in that already-mounted input updates to “Ravi”.', answer: false, why: 'defaultValue is read only on the initial render. To drive the text over time, use a controlled value, or change the key to remount the input.', difficulty: 2 },
      { type: 'fill', q: 'A controlled checkbox gets its on or off state from the ____ prop, not from value.', answer: 'checked', accept: ['checked prop'], why: 'React uses checked (a boolean) for checkboxes and radio buttons, and reads event.target.checked in onChange.', difficulty: 1 },
      { type: 'match', q: 'In a profile form, match each prop or tool to the job it does for an input.', pairs: [['value', 'Makes the input controlled by state'], ['defaultValue', 'Sets only the starting text'], ['ref', 'Lets you read the DOM text when needed'], ['name', 'Lets FormData find the field in a form action']], why: 'Controlled inputs use value; uncontrolled ones use defaultValue plus a ref or a name for FormData.', difficulty: 2 },
    ],
  },
};
